def _ai_render_markdown(text):
    """Very lightweight markdown → HTML (headings, lists, paragraphs, bold)."""
    import html as _html, re as _re
    out = []
    lines = text.split("\n")
    in_list = False
    for ln in lines:
        s = ln.rstrip()
        if not s:
            if in_list:
                out.append("</ul>"); in_list = False
            continue
        esc = _html.escape(s)
        # bold **text**
        esc = _re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", esc)
        esc = _re.sub(r"\*(.+?)\*", r"<em>\1</em>", esc)
        if s.startswith("### "):
            if in_list: out.append("</ul>"); in_list = False
            out.append(f"<h3>{esc[4:]}</h3>")
        elif s.startswith("## "):
            if in_list: out.append("</ul>"); in_list = False
            out.append(f"<h2>{esc[3:]}</h2>")
        elif s.startswith("# "):
            if in_list: out.append("</ul>"); in_list = False
            out.append(f"<h2>{esc[2:]}</h2>")
        elif s.lstrip().startswith(("- ", "* ")):
            if not in_list:
                out.append("<ul>"); in_list = True
            out.append(f"<li>{esc.lstrip()[2:]}</li>")
        else:
            if in_list: out.append("</ul>"); in_list = False
            out.append(f"<p>{esc}</p>")
    if in_list: out.append("</ul>")
    return "\n".join(out)


def _safe_elo_lookup(elo_dict, name, extra_normalizer=None):
    """Robust Elo lookup that handles the three big mismatch sources:
      - exact name (what the dict keys are usually formatted as)
      - case / whitespace variants
      - sport-specific normalization (e.g., full-name → abbr for NFL)
    Returns a float Elo or None if truly unavailable. Fixes the long-
    standing bug where the AI prompt showed 'Elo: 1500' as a placeholder
    whenever the team name didn't exactly match the Elo dict's key."""
    if not elo_dict or not name:
        return None
    # 1. exact
    v = elo_dict.get(name)
    if v is not None:
        return float(v)
    # 2. case-insensitive
    lower_map = {k.lower(): k for k in elo_dict.keys()}
    hit = lower_map.get(name.lower())
    if hit is not None:
        return float(elo_dict[hit])
    # 3. substring/last-token match (handles "Chiefs" vs "Kansas City Chiefs")
    nlow = name.lower()
    for k, v in elo_dict.items():
        klow = k.lower()
        if klow.endswith(nlow) or klow.startswith(nlow) or (nlow.split()[-1] in klow.split()):
            return float(v)
    # 4. sport-specific normalizer (NFL abbr, etc.)
    if extra_normalizer:
        try:
            n2 = extra_normalizer(name)
            if n2 and n2 in elo_dict:
                return float(elo_dict[n2])
        except Exception:
            pass
    return None


def _fmt_elo(elo_val, label="Elo"):
    """Format an Elo value for the AI prompt. 'Elo: 1543' or
    'Elo: unavailable' instead of showing a placeholder 1500 that
    the AI will think is a real rating."""
    if elo_val is None:
        return f"{label}: unavailable"
    return f"{label}: {int(round(elo_val))}"


def _ai_analyze_matchup(sport_slug, game_ctx):
    """Call Claude for a sport-aware game analysis. Returns {html, model, generated_at}."""
    import analyst as analyst_mod
    if not analyst_mod.is_available():
        return {"error": "ANTHROPIC_API_KEY is not set in this environment."}
    try:
        import os
        from anthropic import Anthropic
        client = Anthropic(api_key=os.environ["ANTHROPIC_API_KEY"])
    except Exception as e:
        return {"error": f"anthropic SDK not available: {e}"}

    # Build sport-specific context block
    ctx_lines = []
    if sport_slug == "mlb":
        g = game_ctx
        a = g["away"]; h = g["home"]
        ap = g.get("away_pitcher") or {}; hp = g.get("home_pitcher") or {}
        ctx_lines.append(f"MLB matchup: {a['team']} at {h['team']} · first pitch {g.get('first_pitch','?')}")
        ctx_lines.append(f"- {a['team']}: {a.get('wins','?')}-{a.get('losses','?')}, OPS {a.get('ops','?')}, team ERA {a.get('team_era','?')}")
        ctx_lines.append(f"- {h['team']}: {h.get('wins','?')}-{h.get('losses','?')}, OPS {h.get('ops','?')}, team ERA {h.get('team_era','?')}")
        ctx_lines.append(f"- Away SP: {ap.get('name','?')} ({ap.get('era','?')} ERA, {ap.get('whip','?')} WHIP)")
        ctx_lines.append(f"- Home SP: {hp.get('name','?')} ({hp.get('era','?')} ERA, {hp.get('whip','?')} WHIP)")
        if g.get("p_home") is not None:
            ctx_lines.append(f"- Model prob: home {int(round(g['p_home']*100))}%")
    elif sport_slug in {"epl","laliga","ligamx","ucl","europa","international"}:
        try:
            import soccer_model
            model_slug = sport_slug if sport_slug in {"epl","laliga","ligamx"} else "epl"
            elo = soccer_model.get_final_elo(model_slug) or {}
            h_name = game_ctx.get("home_name",""); a_name = game_ctx.get("away_name","")
            sim = soccer_model.simulate_match(h_name, a_name, model_slug, n=2000)
            h_elo = _safe_elo_lookup(elo, h_name)
            a_elo = _safe_elo_lookup(elo, a_name)
            ctx_lines.append(f"Soccer matchup: {a_name} at {h_name} · kickoff {game_ctx.get('start_time','?')}")
            ctx_lines.append(f"- {_fmt_elo(h_elo, 'home Elo')}, {_fmt_elo(a_elo, 'away Elo')}")
            ctx_lines.append(f"- Dixon-Coles MC: home {sim['home_win_pct']:.1f}% / draw {sim['draw_pct']:.1f}% / away {sim['away_win_pct']:.1f}%")
            ctx_lines.append(f"- Projected goals: {sim['avg_home_goals']:.2f} - {sim['avg_away_goals']:.2f} (BTTS {sim['btts_yes_pct']:.1f}%)")
        except Exception as e:
            ctx_lines.append(f"Soccer context (limited data): {game_ctx.get('home_name','?')} vs {game_ctx.get('away_name','?')}")
    elif sport_slug == "nfl":
        try:
            import nfl_model
            state = nfl_model.get_final_state()
            elo = state.get("final_elo", {}) if state else {}
            qb_elo = state.get("final_qb_elo", {}) if state else {}
            h_name = game_ctx.get("home_name",""); a_name = game_ctx.get("away_name","")
            h_elo = _safe_elo_lookup(elo, h_name, nfl_model.abbr_from_name)
            a_elo = _safe_elo_lookup(elo, a_name, nfl_model.abbr_from_name)
            ctx_lines.append(f"NFL matchup: {a_name} at {h_name} · kickoff {game_ctx.get('start_time','?')}")
            ctx_lines.append(f"- {_fmt_elo(h_elo, 'home team Elo')}, {_fmt_elo(a_elo, 'away team Elo')}")
            if qb_elo:
                h_qb = _safe_elo_lookup(qb_elo, h_name, nfl_model.abbr_from_name)
                a_qb = _safe_elo_lookup(qb_elo, a_name, nfl_model.abbr_from_name)
                ctx_lines.append(f"- {_fmt_elo(h_qb, 'home QB Elo')}, {_fmt_elo(a_qb, 'away QB Elo')}")
        except Exception:
            ctx_lines.append(f"NFL matchup: {game_ctx.get('away_name','?')} at {game_ctx.get('home_name','?')}")
    elif sport_slug == "ncaaf":
        try:
            import cfb_model
            elo = cfb_model.get_or_fit_team_elo() or {}
            h_name = game_ctx.get("home_name",""); a_name = game_ctx.get("away_name","")
            proj_h, proj_a = cfb_model.project_points(h_name, a_name)
            ctx_lines.append(f"NCAAF matchup: {a_name} at {h_name} · kickoff {game_ctx.get('start_time','?')}")
            if cfb_model.is_fitted() and elo:
                h_elo = _safe_elo_lookup(elo, h_name)
                a_elo = _safe_elo_lookup(elo, a_name)
                ctx_lines.append(f"- {_fmt_elo(h_elo, 'home Elo')}, {_fmt_elo(a_elo, 'away Elo')}")
            else:
                ctx_lines.append("- Team Elo: unavailable (CFBD_API_KEY not set; model falls back to spread/total only)")
            ctx_lines.append(f"- Projected points: {proj_h:.1f} - {proj_a:.1f}")
        except Exception:
            ctx_lines.append(f"NCAAF matchup: {game_ctx.get('away_name','?')} at {game_ctx.get('home_name','?')}")
    elif sport_slug == "nhl":
        try:
            import nhl_model
            stats = nhl_model.get_or_fetch_team_stats()
            h_name = game_ctx.get("home_name",""); a_name = game_ctx.get("away_name","")
            hs = stats.get(h_name) or {}; as_ = stats.get(a_name) or {}
            sim = nhl_model.simulate_match(h_name, a_name, n=3000)
            ctx_lines.append(f"NHL matchup: {a_name} at {h_name} · puck drop {game_ctx.get('start_time','?')}")
            ctx_lines.append(f"- Record: home {hs.get('wins',0)}-{hs.get('losses',0)}-{hs.get('ot_losses',0)}, "
                             f"away {as_.get('wins',0)}-{as_.get('losses',0)}-{as_.get('ot_losses',0)}")
            ctx_lines.append(f"- Goals/G: home GF {hs.get('gf_per',0):.2f} GA {hs.get('ga_per',0):.2f}, "
                             f"away GF {as_.get('gf_per',0):.2f} GA {as_.get('ga_per',0):.2f}")
            ctx_lines.append(f"- PP%/PK%: home {(hs.get('pp_pct') or 0)*100:.1f}/{(hs.get('pk_pct') or 0)*100:.1f}, "
                             f"away {(as_.get('pp_pct') or 0)*100:.1f}/{(as_.get('pk_pct') or 0)*100:.1f}")
            ctx_lines.append(f"- Sim: home {sim['home_win_pct']:.1f}% / away {sim['away_win_pct']:.1f}% "
                             f"(λ home {sim['lam_home']:.2f}, away {sim['lam_away']:.2f})")
        except Exception:
            ctx_lines.append(f"NHL matchup: {game_ctx.get('away_name','?')} at {game_ctx.get('home_name','?')}")
    else:
        ctx_lines.append(f"{sport_slug.upper()} matchup: {game_ctx.get('away_name','?')} vs {game_ctx.get('home_name','?')}")

    # Phase 32 enhancements — same signal pipeline tags for every sport:
    #   weather risk + injury scratch (pick_enhancers.D/E)
    #   CLV summary (open vs current line_move_pp)
    #   pick's current signal_score if attached
    try:
        import pick_enhancers as _pe
        h_name = (game_ctx.get("home_name")
                  or (game_ctx.get("home") or {}).get("team") or "")
        a_name = (game_ctx.get("away_name")
                  or (game_ctx.get("away") or {}).get("team") or "")
        start_time = (game_ctx.get("start_time")
                      or game_ctx.get("first_pitch") or "")
        if h_name and start_time:
            try:
                wrisk = _pe.get_weather_risk(sport_slug, h_name, start_time)
            except Exception:
                wrisk = None
            try:
                irisk = _pe.get_injury_risk(sport_slug, h_name, a_name, start_time)
            except Exception:
                irisk = None
            if wrisk and wrisk != "ok":
                ctx_lines.append(f"- Weather: {wrisk} wind risk (impacts totals / passing)")
            if irisk:
                ctx_lines.append(f"- Injury note: {irisk}")
    except Exception:
        pass
    # CLV / line-move summary from the pick itself if attached.
    pk = game_ctx.get("pick") or {}
    try:
        lm = float(pk.get("line_move_pp") or 0.0)
        if abs(lm) >= 0.005:
            direction = "toward our side" if lm > 0 else "away from our side"
            ctx_lines.append(f"- Line move: {lm*100:+.1f}pp {direction} since open")
    except (TypeError, ValueError):
        pass
    sig = pk.get("signal_score")
    if sig is not None:
        ctx_lines.append(f"- Signal composite: {sig}/5 (EV cushion + line move + prob floor + Kalshi agree)")

    context = "\n".join(ctx_lines)
    prompt = f"""You are an expert sports betting analyst with access to the web.
Produce the sharpest, most CURRENT read possible on this matchup. Use web search
to pull in any news from today or the last few days — injury updates, lineup /
starter changes, suspensions, weather, late line movement, public betting
splits, and recent form. Ground your analysis in what the search returns.

{context}

Write 6 sections with markdown headings (## Section):
## News & Injury Report
  — the most recent news items (reporter + source + date if you can).
  Called out injuries, questionable players, suspensions, weather, notable
  late scratches, lineup / rotation / goalie / starting-pitcher news.
## Head-to-Head History
  — recent H2H results between these two sides, home/away splits, any
  stylistic pattern (ex: team A has owned team B at home, totals trend etc).
## Play Styles & Tactical Matchup
  — how each side plays, where they create their edge, and specifically
  how those styles interact (ex: run-heavy offense vs rush defense;
  high-press team vs long-ball; power play vs penalty kill).
## Stat Read
  — pull the key numeric angle(s) from the context block above (model
  Elo / Dixon-Coles projection / Pinnacle fair) and interpret them.
## Risk Flags
  — anything that could blow up your lean: short rest, travel, trap-game
  spots, injury uncertainty, umpire / referee tendencies, late news.
## Lean & Pick
  — one clear recommended play (or "pass" if nothing is actionable).
  Give the market, the price range you'd take, and a confidence tier
  (Lean / Solid / Strong). Avoid filler.

450-650 words. Be specific, cite sources when you use them. If search returns
nothing useful, say so and work from training knowledge rather than inventing.

AT THE VERY END, output EXACTLY ONE machine-readable line in this format
(nothing else on the line, no markdown, exact pipes):

PICK: <market> | <side> | <confidence>

Where
  market     = ML | Spread | Total | BTTS | 1H ML | 1H Total | Team Total | DNB | Distance
  side       = your actual pick label (e.g. "Arsenal ML", "Over 2.5", "Dodgers -1.5")
  confidence = Pass | Lean | Solid | Strong

If no actionable play, write exactly: PICK: Pass | - | Pass"""

    def _attempt(use_search):
        """One API call. Returns (text, stop_reason, used_search, err)."""
        k = dict(
            model=analyst_mod.CLAUDE_MODEL,
            max_tokens=4000,
            messages=[{"role": "user", "content": prompt}],
        )
        if use_search:
            # Anthropic server-side web search tool. If the account doesn't
            # have it enabled we catch the error and fall back.
            k["tools"] = [{
                "type": "web_search_20250305",
                "name": "web_search",
                "max_uses": 5,
            }]
        try:
            resp = client.messages.create(**k)
        except Exception as e:
            return "", None, False, str(e)
        parts = []
        used_search = False
        for block in (resp.content or []):
            btype = getattr(block, "type", None)
            if btype == "text":
                t = getattr(block, "text", "") or ""
                if t:
                    parts.append(t)
            elif btype in ("server_tool_use", "web_search_tool_result", "tool_use"):
                used_search = True
        return "\n\n".join(parts), getattr(resp, "stop_reason", None), used_search, None

    try:
        # First try WITH web search for current news; fall back to no-tool
        # if the account can't use it, or if the response had no text block
        # (e.g. Claude only emitted tool_use/intermediate blocks before stopping).
        text, stop_reason, used_search, err = _attempt(use_search=True)
        tool_err = err
        if not text:
            text2, stop_reason2, _, err2 = _attempt(use_search=False)
            if text2:
                text = text2
                stop_reason = stop_reason2
                used_search = False
            elif err2:
                # Both attempts failed outright
                reason = tool_err or err2
                return {"error": f"Claude call failed: {reason}"}
        if not text:
            return {"error": f"Claude returned no text (stop_reason={stop_reason}, "
                              f"tool_err={tool_err or 'none'})."}
        if used_search:
            text = text + "\n\n*(web search used for current news / injuries)*"
        # Extract the machine-readable PICK: line the prompt asked for.
        parsed_pick = _extract_ai_pick(text, sport_slug, game_ctx)
        # Strip the PICK: line from the rendered narrative so it doesn't
        # also show as prose (the parsed pick is rendered as a chip).
        import re as _re
        clean_text = _re.sub(r'^\s*PICK:\s*.+$', '', text, flags=_re.MULTILINE).strip()
        return {
            "html": _ai_render_markdown(clean_text),
            "pick": parsed_pick,
            "model": analyst_mod.CLAUDE_MODEL,
            "generated_at": datetime.now().isoformat(timespec="seconds"),
        }
    except Exception as e:
        return {"error": f"Claude call failed: {e}"}


def _extract_ai_pick(text, sport_slug, game_ctx):
    """Parse the 'PICK: <market> | <side> | <confidence>' line we told the
    model to emit. Returns a dict with market / side / confidence /
    confidence_cls, or None when the line is absent or marked Pass.

    confidence_cls is one of 'strong', 'solid', 'lean', 'pass' — maps to
    the UI chip colors directly."""
    import re as _re
    m = _re.search(r'PICK:\s*(.+)$', text, flags=_re.MULTILINE)
    if not m:
        return None
    line = m.group(1).strip()
    parts = [p.strip() for p in line.split('|')]
    if len(parts) < 3:
        return None
    market, side, conf = parts[0], parts[1], parts[2]
    conf_norm = conf.lower()
    if conf_norm in ("pass", "none", "-", ""):
        return {"market": "Pass", "side": "-", "confidence": "Pass",
                "confidence_cls": "pass"}
    cls = "lean"
    if "strong" in conf_norm: cls = "strong"
    elif "solid" in conf_norm: cls = "solid"
    elif "lean" in conf_norm:  cls = "lean"
    return {
        "market":         market,
        "side":           side,
        "confidence":     conf.title(),
        "confidence_cls": cls,
    }


@app.route("/ai-analysis", methods=["GET", "POST"])
def ai_analysis_unified():
    """Unified cross-sport AI analysis page."""
    import analyst as analyst_mod
    sport_slug = (request.values.get("sport") or "").lower() or None
    game_id = request.values.get("game") or None

    today_str = datetime.now(CENTRAL).date().isoformat()
    date_str = request.values.get("date") or today_str
    try:
        d_obj = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        d_obj = datetime.now(CENTRAL).date()
        date_str = d_obj.isoformat()
    prev_date = (d_obj - timedelta(days=1)).isoformat()
    next_date = (d_obj + timedelta(days=1)).isoformat()

    sport = sports.by_slug(sport_slug) if sport_slug else None
    sport_name = sport["name"] if sport else ""

    games = []
    analysis = None
    selected_game = None
    sort_mode = (request.values.get("sort") or "signal").lower()
    if sport_slug:
        games = _mc_fetch_games(sport_slug, date_str)
        # Attach each game's "top signal" (max signal_score of any pick
        # on today's board for that game) so we can sort by model
        # conviction instead of alphabetical / kickoff order.
        try:
            today_d = datetime.strptime(date_str, "%Y-%m-%d").date()
            board_rows, _all = _build_board_rows(
                date_str, today_d, sport_slug, strong_only=False)
            top_sig_by_game = {}
            for row in board_rows or []:
                key = (
                    (row.get("home") or "").lower().strip(),
                    (row.get("away") or "").lower().strip(),
                )
                best = 0
                for p in row.get("picks", []):
                    s = int(p.get("signal_score") or 0)
                    if s > best:
                        best = s
                if best:
                    top_sig_by_game[key] = best
            for g in games:
                ctx = g.get("ctx") or {}
                home = (ctx.get("home_name")
                        or (ctx.get("home") or {}).get("team") or "").lower().strip()
                away = (ctx.get("away_name")
                        or (ctx.get("away") or {}).get("team") or "").lower().strip()
                g["top_signal"] = top_sig_by_game.get((home, away), 0)
        except Exception:
            for g in games:
                g.setdefault("top_signal", 0)
        if sort_mode == "signal":
            games = sorted(games,
                           key=lambda g: (-(g.get("top_signal") or 0),
                                          g.get("sort_key") or ""))
        # else keep whatever sort _mc_fetch_games returned (kickoff order)
        if game_id and request.method == "POST":
            selected_game = next((g for g in games if g["id"] == game_id), None)
            if selected_game:
                analysis = _ai_analyze_matchup(sport_slug, selected_game["ctx"])
                # If the AI produced a non-Pass pick, persist it to the
                # daily log so it grades alongside the main board picks.
                # Only save for TODAY — historical dates are read-only.
                try:
                    if (analysis and analysis.get("pick")
                            and analysis["pick"].get("confidence_cls") != "pass"
                            and date_str == today_str):
                        import plays_log
                        ctx = selected_game.get("ctx") or {}
                        home_t = (ctx.get("home_name")
                                  or (ctx.get("home") or {}).get("team")
                                  or "")
                        away_t = (ctx.get("away_name")
                                  or (ctx.get("away") or {}).get("team")
                                  or "")
                        start_time = (ctx.get("start_time")
                                      or ctx.get("first_pitch_utc")
                                      or ctx.get("first_pitch")
                                      or None)
                        pick_label = analysis["pick"].get("side") or ""
                        market_label = analysis["pick"].get("market") or "ML"
                        pid = (f"ai-{sport_slug}-"
                               f"{generic_odds._team_key(away_t)}-"
                               f"{generic_odds._team_key(home_t)}-"
                               f"{abs(hash((market_label, pick_label))) & 0xffffffff:08x}")
                        plays_log.save_daily_picks(date_str, [{
                            "id":             pid,
                            "sport":          sport_name or sport_slug.upper(),
                            "sport_slug":     sport_slug,
                            "home_team":      home_t,
                            "away_team":      away_t,
                            "market":         market_label,
                            "pick":           pick_label,
                            "fair_prob":      None,
                            "pricing_prob":   None,
                            "mc_prob":        None,
                            "consensus_prob": None,
                            "pinnacle_prob":  None,
                            "ev_pct":         None,
                            "decimal":        None,
                            "american":       None,
                            "book":           None,
                            "source":         "ai_analysis",
                            "model_only":     False,
                            "strong":         (analysis["pick"].get("confidence_cls") == "strong"),
                            "start_time":     start_time,
                            "ai_confidence":  analysis["pick"].get("confidence"),
                            "ai_model":       analysis.get("model"),
                        }])
                except Exception:
                    pass

    return render_template_string(
        AI_UNIFIED_TEMPLATE,
        fonts_link=FONTS_LINK,
        shared_style=SHARED_STYLE,
        theme_script=THEME_SCRIPT,
        sport_strip=render_sport_strip("analysis"),
        sport_chip_bar=render_sport_chip_bar(sport_slug, "/ai-analysis", date_str),
        sport_slug=sport_slug,
        sport_name=sport_name,
        games=games,
        game_id=game_id,
        analysis=analysis,
        key_available=analyst_mod.is_available(),
        date_str=date_str,
        date_pretty=d_obj.strftime("%A, %B %d").replace(" 0", " "),
        today_str=today_str,
        prev_date=prev_date,
        next_date=next_date,
        is_today=(date_str == today_str),
        sort_mode=sort_mode,
    )


