def _parse_dk_csv(text):
    """Parse a DK bet-history CSV. Returns ({date_str: [pick_dicts]}, skipped_count).
    Keeps only straight bets with a parseable event, market, selection, odds and status.
    """
    import csv as _csv
    import io as _io
    import re as _re
    reader = _csv.DictReader(_io.StringIO(text))
    def _k(name):
        return (name or "").strip().lower().replace("_", " ").replace("-", " ")
    picks_by_date = {}
    skipped = 0
    for row in reader:
        norm = {_k(k): (v.strip() if isinstance(v, str) else v) for k, v in row.items()}
        date_raw = norm.get("date placed") or norm.get("date") or norm.get("placed")
        event    = norm.get("event") or norm.get("match") or norm.get("game")
        market   = norm.get("market") or norm.get("bet type") or norm.get("market name")
        selection = norm.get("selection") or norm.get("pick") or norm.get("outcome")
        odds_raw  = norm.get("odds") or norm.get("american odds") or norm.get("price")
        stake_raw = norm.get("stake") or norm.get("wager") or norm.get("risk")
        status   = (norm.get("status") or norm.get("result") or "").lower()
        profit_raw = norm.get("profit") or norm.get("profit/loss") or norm.get("p/l")

        if not (date_raw and event and selection and odds_raw):
            skipped += 1
            continue
        # DK parlay rows typically say "Parlay" or "Multi" somewhere
        if "parlay" in (market or "").lower() or "multi" in (market or "").lower():
            skipped += 1
            continue
        try:
            m = _re.search(r"[+-]?\d+", odds_raw.replace(",", ""))
            if not m:
                raise ValueError("no odds")
            american = int(m.group(0))
            stake = float(_re.search(r"-?\d+(?:\.\d+)?", (stake_raw or "0").replace("$","").replace(",","")).group(0))
        except Exception:
            skipped += 1
            continue
        try:
            ds = _normalize_date(date_raw)
        except Exception:
            skipped += 1
            continue
        decimal = mlb_odds.american_to_decimal(american)
        if "won" in status:
            result = "W"; profit_u = (decimal - 1.0)
        elif "lost" in status or "lose" in status:
            result = "L"; profit_u = -1.0
        elif "push" in status or "void" in status or "canc" in status:
            result = "P"; profit_u = 0.0
        else:
            result = None; profit_u = 0.0

        teams = _re.split(r"\s+(?:vs\.?|at|@|-)\s+", event, maxsplit=1)
        away = teams[0].strip() if len(teams) == 2 else event
        home = teams[1].strip() if len(teams) == 2 else ""

        bet_id = f"dk-{ds}-{abs(hash((event, market, selection, american, stake))) & 0xffffffff:08x}"
        pick = {
            "id":            bet_id,
            "sport":         "DK",
            "sport_slug":    "dk",
            "home_team":     home,
            "away_team":     away,
            "market":        market or "ML",
            "pick":          selection,
            "decimal":       decimal,
            "american":      american,
            "book":          "draftkings",
            "source":        "book_dk",
            "model_only":    False,
            "strong":        False,
            "stake":         stake,
            "result":        result,
            "profit_u":      profit_u,
        }
        picks_by_date.setdefault(ds, []).append(pick)
    return picks_by_date, skipped


def _normalize_date(raw):
    """Parse a DK date string ('10/5/2026 1:23 PM EDT' or '2026-10-05') into YYYY-MM-DD."""
    from datetime import datetime as _dt
    raw = (raw or "").strip()
    # Trim trailing tz if present
    for sep in (" EDT", " EST", " CDT", " CST", " PDT", " PST", " UTC"):
        if raw.endswith(sep):
            raw = raw[: -len(sep)]
            break
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M", "%Y-%m-%d",
                "%m/%d/%Y %I:%M %p", "%m/%d/%Y %H:%M", "%m/%d/%Y",
                "%m/%d/%y %I:%M %p", "%m/%d/%y", "%b %d, %Y %I:%M %p",
                "%b %d, %Y"):
        try:
            return _dt.strptime(raw, fmt).date().isoformat()
        except ValueError:
            continue
    raise ValueError(f"unparseable date: {raw!r}")


@app.route("/logged/regrade")
def logged_regrade():
    """Force a re-grade pass for all logged dates (or one date via ?date=).
    Bypasses the normal 'skip if all settled' short-circuit so corrected
    graders (new markets, bug fixes) and freshly-arrived scores both apply.

    Pass ?rescore=1 to ALSO drop any prior W/L/P and re-evaluate every
    pick from scratch — needed when the matching/scoring logic changes
    (not just when a new score arrives). Default stays conservative so
    routine refreshes don't flip settled picks.

    All-dates mode walks 7 days back (not 14) so the pass fits inside
    the gunicorn worker budget on free tier. For deeper history,
    rescore date-by-date via ?date=YYYY-MM-DD."""
    import plays_log, sports as _sports
    from flask import redirect
    date_str = request.args.get("date")
    rescore  = request.args.get("rescore") in ("1", "true", "yes")
    sport_key_by_slug = {s["slug"]: s.get("odds_api_key") for s in _sports.SPORTS}
    try:
        if date_str:
            plays_log.grade_date(date_str, sport_key_by_slug,
                                  force=True, rescore=rescore)
        else:
            for ds in plays_log.all_logged_dates(limit=7):
                plays_log.grade_date(ds, sport_key_by_slug,
                                      force=True, rescore=rescore)
        # Bust the 60s grade_all cache so the very next /logged render
        # reflects the fresh grades instead of a stale snapshot.
        try:
            plays_log.invalidate_grade_all_cache()
        except Exception:
            pass
    except Exception:
        pass
    return redirect("/logged", code=302)


@app.route("/whatsnew")
def whats_new():
    """Phase 29 (10): in-app changelog. Pulls the last 25 commits
    from git log and groups by phase."""
    import subprocess, os as _os_wn
    try:
        out = subprocess.check_output(
            ["git", "log", "-25", "--pretty=%s|||%ad", "--date=short"],
            cwd=_os_wn.path.dirname(_os_wn.path.abspath(__file__)),
            stderr=subprocess.DEVNULL, timeout=5,
        ).decode("utf-8", errors="replace")
        lines = []
        for line in out.splitlines():
            if "|||" in line:
                subj, date = line.split("|||", 1)
                lines.append({"subject": subj.strip(), "date": date.strip()})
    except Exception:
        lines = []
    html = (
        FONTS_LINK + SHARED_STYLE
        + '<main class="wrap" style="max-width:780px">'
        + '<h1>What\'s new</h1>'
        + '<p class="sub" style="color:var(--muted);font-size:14px">Recent changes to the picks pipeline, filters, and UI. Shows the last 25 commits on main.</p>'
        + '<div style="display:flex;flex-direction:column;gap:10px;margin-top:16px">'
    )
    if not lines:
        html += '<div style="color:var(--muted)">No git log available on this instance.</div>'
    for ln in lines:
        html += (
            '<div style="padding:10px 14px;background:var(--card);border:1px solid var(--rule);border-radius:8px">'
            f'<div style="font-family:JetBrains Mono,monospace;font-size:11px;color:var(--muted-2);letter-spacing:0.1em">{ln["date"]}</div>'
            f'<div style="font-size:14px;color:var(--ink);margin-top:2px">{ln["subject"]}</div>'
            '</div>'
        )
    html += '</div></main>' + THEME_SCRIPT
    return html


import os as _settings_os
_SETTINGS_PATH = _settings_os.path.join(
    _settings_os.path.dirname(_settings_os.path.abspath(__file__)),
    "logs", "user_settings.json",
)
_LOCK_SENT_PATH = _settings_os.path.join(
    _settings_os.path.dirname(_settings_os.path.abspath(__file__)),
    "logs", "lock_webhook_sent.json",
)


_SETTINGS_ENV_KEYS = {
    "discord_webhook_url":      "DISCORD_WEBHOOK_URL",
    "pushover_user_key":        "PUSHOVER_USER_KEY",
    "pushover_api_token":       "PUSHOVER_API_TOKEN",
    "daily_picks_webhook_url":  "DAILY_PICKS_WEBHOOK_URL",
    "cron_secret":              "CRON_SECRET",
    "discord_bot_token":        "DISCORD_BOT_TOKEN",
}


def _load_settings():
    """Load user settings from logs/user_settings.json, with fallback
    chain for sensitive fields so they survive Render's ephemeral
    filesystem (logs/ is wiped on every spin-down / deploy).

    Fallback order for each sensitive field:
      1. Plain-text local file (logs/user_settings.json)
      2. Encrypted mirror via log_persist (logs/user_settings.enc on
         the data branch, decrypted with SETTINGS_SYNC_KEY env var)
      3. Render env var (DAILY_PICKS_WEBHOOK_URL, etc.)
      4. Render Secret File (/etc/secrets/<NAME>)
    """
    defaults = {
        "bankroll": 1000,
        "kelly_fraction": 0.25,
        "discord_webhook_url": "",
        "pushover_user_key":   "",
        "pushover_api_token":  "",
        "daily_picks_webhook_url": "",
        "cron_secret": "",
        "discord_bot_token": "",
    }
    try:
        import json
        with open(_SETTINGS_PATH) as f:
            d = json.load(f) or {}
    except Exception:
        d = {}
    out = {**defaults, **d}
    # Encrypted-mirror fallback (shipped 2026-10-22): any sensitive
    # field blank in the local file gets filled from the Fernet-
    # encrypted copy on the data branch via log_persist. This fires
    # right after Render wipes logs/ on a deploy and restores the
    # webhook URL + other secrets automatically, without the operator
    # having to re-save /settings. Requires SETTINGS_SYNC_KEY env
    # var; no-op without.
    try:
        _restore_sensitive_settings(out)
    except Exception:
        pass
    # Env-var + Secret File fallback — unchanged behavior.
    for key, env_name in _SETTINGS_ENV_KEYS.items():
        if out.get(key):
            continue
        v = _settings_os.environ.get(env_name)
        if not v:
            # Try Render Secret File — mounted at /etc/secrets/<name>.
            # Also try lowercase, since the user may have named the
            # secret file after the settings-form field.
            for cand in (env_name, key, env_name.lower()):
                try:
                    with open(f"/etc/secrets/{cand}") as f:
                        v = f.read().strip()
                    if v:
                        break
                except Exception:
                    continue
        if v:
            out[key] = v
    return out


_SETTINGS_SYNC_PATH = "logs/user_settings.enc"  # path INSIDE the data branch
_SETTINGS_SYNC_FIELDS = (
    "discord_webhook_url",
    "daily_picks_webhook_url",
    "pushover_user_key",
    "pushover_api_token",
    "cron_secret",
    "discord_bot_token",
)


def _settings_fernet():
    """Return a Fernet cipher if SETTINGS_SYNC_KEY is set, else None.
    The key is a 32-byte url-safe base64 string generated with
    `python -c "from cryptography.fernet import Fernet; print(Fernet.generate_key().decode())"`
    and stored as a Render env var (NOT in Secret Files, which would
    defeat the purpose — the point is to NOT need Secret Files)."""
    k = _settings_os.environ.get("SETTINGS_SYNC_KEY", "").strip()
    if not k:
        return None
    try:
        from cryptography.fernet import Fernet
        return Fernet(k.encode() if isinstance(k, str) else k)
    except Exception:
        return None


def _mirror_sensitive_settings(d):
    """Encrypt sensitive-only settings and mirror through log_persist so
    they survive deploys (Render wipes logs/ on each deploy, blanking
    the plain-text user_settings.json file). Non-sensitive settings
    like bankroll and kelly_fraction are left in the plain file —
    those don't need protection and reconstruct fine from defaults.

    No-op (safe fallback) when SETTINGS_SYNC_KEY env var isn't set —
    user has to opt in by generating a key and setting it on Render.
    This is deliberate: without the key, mirroring would leak the
    webhook URL to the PUBLIC data branch on GitHub."""
    global _RESTORED_CACHE, _RESTORED_ATTEMPTED
    cipher = _settings_fernet()
    if cipher is None:
        return False
    try:
        import json as _j
        sensitive = {k: d.get(k) for k in _SETTINGS_SYNC_FIELDS
                     if d.get(k)}
        if not sensitive:
            return False
        payload = _j.dumps(sensitive).encode()
        enc = cipher.encrypt(payload).decode()  # ascii-safe
        import log_persist
        log_persist.write_file(_SETTINGS_SYNC_PATH, enc)
        # Keep the process-lifetime cache in sync with what we just
        # wrote. Future _load_settings calls in this process see the
        # fresh values without another GitHub read.
        _RESTORED_CACHE = sensitive
        _RESTORED_ATTEMPTED = True
        return True
    except Exception:
        return False


# Process-lifetime cache for the decrypted mirror. Populated the first
# time _restore_sensitive_settings succeeds; cleared whenever the user
# saves /settings (that save triggers a fresh encrypt+push). Keeps
# every _load_settings call from hitting GitHub (log_persist does an
# HTTPS roundtrip per read).
_RESTORED_CACHE = None  # None = not yet attempted; {} = tried, nothing
_RESTORED_ATTEMPTED = False


def _restore_sensitive_settings(d):
    """Pull encrypted-mirror sensitive settings from log_persist and
    merge them into d (only for fields d doesn't already have). Called
    from _load_settings when the local plain file is missing/empty
    (eg right after a Render deploy wiped logs/). No-op without
    SETTINGS_SYNC_KEY.

    Caches across the lifetime of the process so we only hit GitHub
    once per boot — _load_settings is called on every page load and
    every dispatcher tick, so uncached we would exhaust GitHub's rate
    limit and add 300-500ms to every request."""
    global _RESTORED_CACHE, _RESTORED_ATTEMPTED
    cipher = _settings_fernet()
    if cipher is None:
        return False
    if not _RESTORED_ATTEMPTED:
        _RESTORED_ATTEMPTED = True
        try:
            import log_persist
            enc, _sha = log_persist.read_file(_SETTINGS_SYNC_PATH)
            if enc:
                import json as _j
                plain = cipher.decrypt(enc.encode()).decode()
                _RESTORED_CACHE = _j.loads(plain) or {}
            else:
                _RESTORED_CACHE = {}
        except Exception:
            _RESTORED_CACHE = {}
    if not _RESTORED_CACHE:
        return False
    changed = False
    for k, v in _RESTORED_CACHE.items():
        if v and not d.get(k):
            d[k] = v
            changed = True
    return changed


def _save_settings(d):
    try:
        import json
        _settings_os.makedirs(_settings_os.path.dirname(_SETTINGS_PATH), exist_ok=True)
        with open(_SETTINGS_PATH, "w") as f:
            json.dump(d, f)
    except Exception:
        return False
    # Mirror sensitive fields through log_persist (encrypted). Non-
    # blocking — if the mirror fails or no SETTINGS_SYNC_KEY is set,
    # the local save still succeeded.
    try:
        _mirror_sensitive_settings(d)
    except Exception:
        pass
    return True


# Phase 30 (#1): webhook alerts for Signal 5/5 LOCK picks. Dedupe via a
# small JSON of pick-ids we've already pinged for; survives Render
# restarts because logs/ is mirrored to GitHub.
_LOCK_WEBHOOK_LOCK = _threading.Lock()


def _lock_sent_ids():
    try:
        import json
        with open(_LOCK_SENT_PATH) as f:
            return set(json.load(f) or [])
    except Exception:
        return set()


def _mark_lock_sent(ids):
    try:
        import json
        _settings_os.makedirs(_settings_os.path.dirname(_LOCK_SENT_PATH), exist_ok=True)
        with open(_LOCK_SENT_PATH, "w") as f:
            json.dump(sorted(ids)[:400], f)   # cap size, old ids drop off
    except Exception:
        pass


def _format_lock_message(pick):
    """One-line message for Discord / Pushover push."""
    sport = pick.get("sport_name") or pick.get("sport") or "?"
    text  = pick.get("pick") or "?"
    away  = pick.get("away_team") or pick.get("game_away") or ""
    home  = pick.get("home_team") or pick.get("game_home") or ""
    ev    = pick.get("ev_pct")
    dec   = pick.get("decimal")
    book  = pick.get("book") or "pinnacle"
    parts = [f":lock: LOCK (Signal 5/5)  —  {text}"]
    if away and home:
        parts.append(f"{sport}  {away} @ {home}")
    extra = []
    if ev is not None:
        try: extra.append(f"+{float(ev):.1f}% EV")
        except (TypeError, ValueError): pass
    if dec:
        try: extra.append(f"@ {float(dec):.2f} ({book})")
        except (TypeError, ValueError): pass
    if extra:
        parts.append("  ·  ".join(extra))
    return "\n".join(parts)


def _send_discord(webhook_url, message):
    try:
        from urllib.request import Request, urlopen
        import json
        data = json.dumps({"content": message}).encode()
        req = Request(webhook_url, data=data, method="POST",
                      headers={
                          "Content-Type": "application/json",
                          "User-Agent": "cheeks-model/1.0 (+https://cheeks-model.onrender.com)",
                      })
        urlopen(req, timeout=10).close()
        return True
    except Exception:
        return False


def _send_pushover(user_key, api_token, message, title="LOCK pick"):
    try:
        from urllib.request import Request, urlopen
        from urllib.parse import urlencode
        data = urlencode({
            "token":   api_token,
            "user":    user_key,
            "message": message,
            "title":   title,
            "priority": "0",
        }).encode()
        req = Request("https://api.pushover.net/1/messages.json",
                      data=data, method="POST")
        urlopen(req, timeout=5).close()
        return True
    except Exception:
        return False


def _maybe_notify_locks(star_picks):
    """Fire-and-forget webhook alerts for freshly-identified Signal 5/5
    picks on today's board. Dedupes against lock_webhook_sent.json so
    the same pick is pushed at most once ever."""
    try:
        settings = _load_settings()
        discord = (settings.get("discord_webhook_url") or "").strip()
        pu_user = (settings.get("pushover_user_key") or "").strip()
        pu_tok  = (settings.get("pushover_api_token") or "").strip()
        if not (discord or (pu_user and pu_tok)):
            return
        locks = [p for p in star_picks
                 if (p.get("signal_score") or 0) >= 5
                 and not p.get("do_not_bet")]
        if not locks:
            return
        with _LOCK_WEBHOOK_LOCK:
            sent = _lock_sent_ids()
            new = [p for p in locks if p.get("id") and p.get("id") not in sent]
            if not new:
                return
            for p in new:
                msg = _format_lock_message(p)
                if discord:
                    _send_discord(discord, msg)
                if pu_user and pu_tok:
                    _send_pushover(pu_user, pu_tok, msg)
                sent.add(p["id"])
            _mark_lock_sent(sent)
    except Exception:
        pass


# Phase 31: Daily picks PNG + live change-alerts to Discord.
_CHANGE_WEBHOOK_LOCK = _threading.Lock()


def _maybe_notify_changes(star_picks):
    """Fire-and-forget mid-slate alerts for the daily-picks Discord
    channel. v2 rules — much quieter than before:
    - No candidate / entrant alerts at all. Picks are locked once
      posted; late-blooming picks wait for the next slate.
    - Hard DNB only (signal drops to <= 1 or do_not_bet flag flips).
      Deduped per pick id per day. Alert names the slate.
    - Per-pick result alerts fire as soon as a posted pick grades.
      One PNG per pick per day."""
    try:
        settings = _load_settings()
        webhook = (settings.get("daily_picks_webhook_url") or "").strip()
        if not webhook:
            return
        try:
            import discord_bot as _db
        except Exception:
            return
        sched = _load_dispatch_schedule()
        slates = (sched.get("slates") or {}) if sched else {}
        posted_by_slate = {}
        posted_pairs = []
        for s_str, meta in slates.items():
            s = int(s_str)
            ids = meta.get("pick_ids") or []
            if ids and meta.get("sent"):
                posted_by_slate[s] = ids
                label = {1: "Morning", 2: "Afternoon", 3: "Prime Time"}.get(s, f"Slate {s}")
                for pid in ids:
                    posted_pairs.append((pid, label))
        if not posted_by_slate:
            return
        with _CHANGE_WEBHOOK_LOCK:
            dnb_alerts = _db.diff_posted_hard_dnb(star_picks, posted_by_slate)
            if dnb_alerts:
                _db.send_change_alert(webhook, entrants=[], dnb_alerts=dnb_alerts)
            # Per-pick result PNGs disabled — results consolidated into
            # the once-per-day EOD summary slide.
    except Exception:
        pass


def _suggested_units(pick, bankroll, kelly_frac):
    """Fractional-Kelly suggested stake in units for a pick card.
    Returns None if we can't compute it (missing probs/odds)."""
    try:
        fp  = float(pick.get("fair_prob") or 0.0)
        dec = float(pick.get("decimal") or 0.0)
    except (TypeError, ValueError):
        return None
    if dec <= 1.01 or fp <= 0 or fp >= 1:
        return None
    b = dec - 1.0
    q = 1.0 - fp
    kelly = (fp * b - q) / b
    if kelly <= 0:
        return None
    stake_frac = kelly * max(0.0, min(1.0, kelly_frac))
    units = stake_frac * bankroll / 100.0  # 100 units == full bankroll convention
    return round(units, 2) if units >= 0.05 else None


def _send_slate_png(slate):
    """Post one slate's top-5 picks for the given slate window
    (1 Morning / 2 Afternoon / 3 Prime Time). Returns a dict with sent
    count + posted pick_ids."""
    try:
        import discord_bot as _db
    except Exception:
        return {"sent": 0, "error": "pillow_missing", "pick_ids": []}
    settings = _load_settings()
    webhook = (settings.get("daily_picks_webhook_url") or "").strip()
    if not webhook:
        return {"sent": 0, "error": "no_webhook", "pick_ids": []}
    try:
        _d = datetime.now(CENTRAL).date()
        _date_str = _d.isoformat()
        board_rows, _all = _build_board_rows(_date_str, _d, "all",
                                              strong_only=False)
    except Exception:
        return {"sent": 0, "error": "board_build_failed", "pick_ids": []}
    # Persist today's picks to plays_log. The TODAY (/) page doesn't
    # save; only /sport/<slug> does. If the user drives the app purely
    # via the Discord feed, no picks would ever get logged or graded.
    # Save every pick that cleared the current filter so /logged
    # populates and the grader has something to grade.
    try:
        import plays_log as _pl
        to_save = []
        seen_ids = set()
        for row in board_rows or []:
            for p in row.get("picks", []):
                pid = p.get("id")
                if not pid or pid in seen_ids:
                    continue
                if (p.get("signal_score") or 0) >= 3 and not p.get("do_not_bet"):
                    to_save.append({**p, "model_only": False})
                    seen_ids.add(pid)
        if to_save:
            _pl.save_daily_picks(_date_str, to_save)
    except Exception:
        pass
    flat = []
    for row in board_rows or []:
        for p in row.get("picks", []):
            if (p.get("signal_score") or 0) >= 3 and not p.get("do_not_bet"):
                flat.append(p)
    if not flat:
        # Terminal reason — the dispatcher must NOT retry forever when
        # the board legitimately has no qualifying picks. Previously
        # this returned no `reason` field, which fell through the
        # dispatcher's _TERMINAL_REASONS check and kept retrying up to
        # _MAX_SLATE_ATTEMPTS (burning 6 ticks before giving up).
        return {"sent": 0, "picks": 0, "slate": slate, "pick_ids": [],
                "reason": "no_webhook_or_no_board"}
    date_label = datetime.now(CENTRAL).strftime("%A, %B %d")
    r = _db.send_slate_picks(webhook, flat, date_label=date_label, slate=slate)
    if r.get("sent") and r.get("pick_ids"):
        # Log posted ids so /logged can show a dedicated "Discord posted"
        # record alongside the current filter.
        _record_discord_posted(_date_str, r["pick_ids"])
    return {"sent":    r.get("sent", 0),
            "picks":   len(flat),
            "slate":   slate,
            "pick_ids": r.get("pick_ids", []),
            "reason":  r.get("reason")}


# Legacy wrapper kept so /cron/daily-picks still works.
def _send_daily_picks_png(half=None):
    """Legacy: half=1 → slate 1; half=2 → whichever of slates 2/3 fires."""
    if half == 1:
        return _send_slate_png(1)
    if half == 2:
        for s in (2, 3):
            r = _send_slate_png(s)
            if r.get("sent"):
                return r
        return {"sent": 0, "picks": 0, "half": 2, "pick_ids": []}
    # No arg → fire slate 1 as a reasonable default.
    return _send_slate_png(1)


@app.route("/cron/daily-picks")
def cron_daily_picks():
    """RETIRED. The slate-based pipeline (two PNG posts per day of top-N
    picks) was replaced by Agent #8 — the per-pick moderator — which
    posts individually when each pick is in its sport's pre-game window
    AND clears the evidence-score threshold. See /cron/moderator-tick.
    Kept as a 200 no-op so legacy UptimeRobot monitors stay green."""
    return Response(json.dumps({
        "ok": True,
        "retired": True,
        "replaced_by": "/cron/moderator-tick",
        "note": ("Legacy slate pipeline retired on 2026-10-23. Point "
                 "your cron at /cron/moderator-tick (every 10 min) and "
                 "/cron/eod-recap (daily)."),
    }), mimetype="application/json")


# Phase 31 orchestrator — one Render cron hits /cron/dispatch every
# 15 min; this computes/loads the day's schedule and fires whatever's
# due (agenda, half-1 picks, half-2 picks, half-1 results, half-2
# results). State persists in logs/discord_schedule.json for the day.
_DISCORD_SCHEDULE_PATH = _settings_os.path.join(
    _settings_os.path.dirname(_settings_os.path.abspath(__file__)),
    "logs", "discord_schedule.json",
)
_DISCORD_SCHEDULE_PRIOR_PATH = _settings_os.path.join(
    _settings_os.path.dirname(_settings_os.path.abspath(__file__)),
    "logs", "discord_schedule_prior.json",
)
_DISCORD_POSTED_PATH = _settings_os.path.join(
    _settings_os.path.dirname(_settings_os.path.abspath(__file__)),
    "logs", "discord_posted.json",
)
_DISCORD_FIRED_PATH = _settings_os.path.join(
    _settings_os.path.dirname(_settings_os.path.abspath(__file__)),
    "logs", "discord_fired_events.json",
)
_DISPATCH_HEARTBEAT_PATH = _settings_os.path.join(
    _settings_os.path.dirname(_settings_os.path.abspath(__file__)),
    "logs", "discord_dispatch_heartbeat.json",
)
# Serializes dispatcher ticks so concurrent UptimeRobot / manual / GH
# Actions pings don't race each other into double-posting events.
_DISPATCH_LOCK = _threading.Lock()

# In-memory ring buffer of the last few dispatcher errors so we don't
# have to swallow them silently in the risky `except Exception: pass`
# sites. Surfaces on /debug/dispatch. Not persisted — reset on every
# instance restart, which is fine since the dashboard is operational
# diagnostics, not long-term audit.
_DISPATCH_ERRORS = []
_DISPATCH_ERROR_LOCK = _threading.Lock()
_DISPATCH_ERRORS_MAX = 20


def _record_dispatch_error(context, exc):
    """Store (ts, context, exception type + str) in a bounded ring
    buffer. Used to replace risky silent swallows in the dispatcher
    body so operators can see failures on /debug/dispatch instead of
    having to grep stdout logs."""
    try:
        ts = datetime.now(CENTRAL).isoformat(timespec="seconds")
        entry = {"ts": ts, "context": context,
                 "error": f"{type(exc).__name__}: {str(exc)[:200]}"}
        with _DISPATCH_ERROR_LOCK:
            _DISPATCH_ERRORS.append(entry)
            if len(_DISPATCH_ERRORS) > _DISPATCH_ERRORS_MAX:
                del _DISPATCH_ERRORS[0:len(_DISPATCH_ERRORS) - _DISPATCH_ERRORS_MAX]
    except Exception:
        pass


def _load_fired_events():
    """Return set of 'YYYY-MM-DD:event' keys we've already posted to
    Discord. Checked LOCAL first, then GitHub mirror (survives Render
    spin-down wipes). Memoized briefly to avoid hammering disk."""
    try:
        with open(_DISCORD_FIRED_PATH) as f:
            data = json.load(f) or {}
            return set(data.get("fired") or [])
    except Exception:
        pass
    try:
        import log_persist
        if log_persist.is_configured():
            text, _sha = log_persist.read_file("logs/discord_fired_events.json")
            if text:
                data = json.loads(text) or {}
                return set(data.get("fired") or [])
    except Exception:
        pass
    return set()


def _mark_fired(key):
    """Add `key` to the fired-events set, write LOCAL + GitHub mirror.
    Idempotent — safe to call multiple times for the same key."""
    fired = _load_fired_events()
    if key in fired:
        return
    fired.add(key)
    # Prune anything older than 7 days so the set doesn't grow forever.
    today = datetime.now(CENTRAL).date()
    keep = set()
    for k in fired:
        try:
            d_str = k.split(":", 1)[0]
            dt = datetime.fromisoformat(d_str).date()
            if (today - dt).days <= 7:
                keep.add(k)
        except Exception:
            keep.add(k)  # malformed → keep safely
    try:
        _settings_os.makedirs(_settings_os.path.dirname(_DISCORD_FIRED_PATH),
                               exist_ok=True)
        with open(_DISCORD_FIRED_PATH, "w") as f:
            json.dump({"fired": sorted(keep)}, f)
    except Exception:
        pass
    try:
        import log_persist
        if log_persist.is_configured():
            log_persist.write_file("logs/discord_fired_events.json",
                                    json.dumps({"fired": sorted(keep)}),
                                    message="discord fired-event dedup update")
    except Exception:
        pass


def _already_fired(key):
    """Shortcut: True if `key` is in the fired-events set."""
    return key in _load_fired_events()


# In-memory cache for the Discord-posted log so /logged (which calls
# the predicate once per pick, hundreds of times) doesn't hit disk on
# every call. Invalidated when _record_discord_posted writes.
_DISCORD_POSTED_CACHE = {"data": None, "ts": 0.0}
_DISCORD_POSTED_CACHE_TTL = 60.0  # seconds


def _load_discord_posted_log():
    """Return {date_iso: [pick_ids]} dict of picks posted to Discord.
    Memoized for _DISCORD_POSTED_CACHE_TTL seconds. Falls back to the
    GitHub mirror when the local file is empty (Render spin-down wipes
    logs/, but the GitHub-mirrored copy persists)."""
    import time as _t
    now = _t.time()
    if (_DISCORD_POSTED_CACHE["data"] is not None
            and (now - _DISCORD_POSTED_CACHE["ts"]) < _DISCORD_POSTED_CACHE_TTL):
        return _DISCORD_POSTED_CACHE["data"]
    data = {}
    try:
        with open(_DISCORD_POSTED_PATH) as f:
            data = json.load(f) or {}
    except Exception:
        pass
    if not data:
        try:
            import log_persist
            if log_persist.is_configured():
                text, _sha = log_persist.read_file("logs/discord_posted.json")
                if text:
                    data = json.loads(text) or {}
                    # Persist locally so we don't hit GitHub every call.
                    try:
                        _settings_os.makedirs(
                            _settings_os.path.dirname(_DISCORD_POSTED_PATH),
                            exist_ok=True)
                        with open(_DISCORD_POSTED_PATH, "w") as f:
                            f.write(text)
                    except Exception:
                        pass
        except Exception:
            pass
    _DISCORD_POSTED_CACHE["data"] = data
    _DISCORD_POSTED_CACHE["ts"]   = now
    return data


def _record_discord_posted(date_str, pick_ids):
    """Append pick_ids to the Discord-posted log for a given date, cap
    at 180 days, mirror to GitHub via log_persist so the record
    survives Render's ephemeral-fs wipes."""
    if not date_str or not pick_ids:
        return
    data = _load_discord_posted_log()
    existing = set(data.get(date_str) or [])
    existing.update(pick_ids)
    data[date_str] = sorted(existing)
    if len(data) > 180:
        for d in sorted(data.keys())[:-180]:
            del data[d]
    try:
        _settings_os.makedirs(_settings_os.path.dirname(_DISCORD_POSTED_PATH),
                               exist_ok=True)
        with open(_DISCORD_POSTED_PATH, "w") as f:
            json.dump(data, f)
    except Exception:
        pass
    try:
        import log_persist
        if log_persist.is_configured():
            log_persist.write_file("logs/discord_posted.json",
                                    json.dumps(data),
                                    message="discord posted log update")
    except Exception:
        pass
    # Invalidate the in-memory cache so the next predicate call sees
    # the updated set.
    _DISCORD_POSTED_CACHE["data"] = None


def _passes_discord_posted(pick):
    """Predicate: True if this pick's id appears in the Discord-posted
    log for its date. Requires `_date` to be injected on the pick
    (logged_plays does this before applying predicates)."""
    date_str = pick.get("_date")
    pick_id  = pick.get("id")
    if not date_str or not pick_id:
        return False
    data = _load_discord_posted_log()
    return pick_id in set(data.get(date_str) or [])


def _load_dispatch_schedule():
    try:
        with open(_DISCORD_SCHEDULE_PATH) as f:
            return json.load(f) or {}
    except Exception:
        return {}


def _save_dispatch_schedule(d):
    """Persist the dispatcher's day-state to both the local file AND the
    GitHub mirror so it survives Render spin-downs mid-day. Previously
    only wrote locally, which meant any pick_ids captured on a slate
    fire were lost if the Render instance spun down before the next
    scheduled fire — the recompute-on-stale path then rebuilt an empty
    schedule and the slate's picks appeared as 0 on the next tick."""
    try:
        _settings_os.makedirs(_settings_os.path.dirname(_DISCORD_SCHEDULE_PATH),
                               exist_ok=True)
        with open(_DISCORD_SCHEDULE_PATH, "w") as f:
            json.dump(d, f)
    except Exception:
        pass
    try:
        import log_persist
        if log_persist.is_configured():
            log_persist.write_file("logs/discord_schedule.json",
                                    json.dumps(d),
                                    message="dispatcher state update")
    except Exception:
        pass


def _load_prior_dispatch_schedule():
    try:
        with open(_DISCORD_SCHEDULE_PRIOR_PATH) as f:
            return json.load(f) or {}
    except Exception:
        pass
    # Fallback 1: GitHub mirror of prior schedule
    try:
        import log_persist
        if log_persist.is_configured():
            text, _sha = log_persist.read_file("logs/discord_schedule_prior.json")
            if text:
                return json.loads(text)
    except Exception:
        pass
    # Fallback 2: synthesize prior state from discord_posted.json for
    # YESTERDAY. Covers the case where the state file was lost at
    # midnight rollover (Render spin-down) before the prior-schedule
    # mirror caught up. We can't recover exact slate attribution, so
    # we park every posted id in slate 0 — the EOD renderer treats
    # slate 0 as "Day's picks" rather than mis-labelling as any one
    # slate. Previously this fallback dumped everything into slate 3
    # (Prime Time), which is why some EOD summaries only showed the
    # prime-time slice.
    try:
        posted = _load_discord_posted_log()
        if not posted:
            return {}
        yesterday = (datetime.now(CENTRAL).date() - timedelta(days=1)).isoformat()
        ids = posted.get(yesterday) or []
        if not ids:
            return {}
        return {
            "version": 2,
            "date":    yesterday,
            "slates": {
                "0": {"pick_ids": ids, "sent": True,
                      "label_override": "Day"},
            },
            "eod": {"sent": False, "post_at_iso": None},
        }
    except Exception:
        return {}


def _save_prior_dispatch_schedule(d):
    try:
        _settings_os.makedirs(_settings_os.path.dirname(_DISCORD_SCHEDULE_PRIOR_PATH),
                               exist_ok=True)
        with open(_DISCORD_SCHEDULE_PRIOR_PATH, "w") as f:
            json.dump(d, f)
    except Exception:
        pass
    try:
        import log_persist
        if log_persist.is_configured():
            log_persist.write_file("logs/discord_schedule_prior.json",
                                    json.dumps(d),
                                    message="dispatch prior-day state")
    except Exception:
        pass
    # Mirror to GitHub so the state survives Render's ephemeral-fs
    # wipes (every 15-min spin-down and every deploy). If log_persist
    # isn't configured, this silently no-ops.
    try:
        import log_persist
        if log_persist.is_configured():
            log_persist.write_file("logs/discord_schedule.json",
                                    json.dumps(d),
                                    message="dispatch state update")
    except Exception:
        pass


def _load_dispatch_schedule_remote_fallback():
    """When logs/ was just wiped, try to pull the latest schedule back
    from GitHub so we don't blindly recompute (and re-fire 'sent'
    events). Returns {} on any failure.

    log_persist.read_file returns (text, sha) — hence the unpacking."""
    try:
        import log_persist
        if not log_persist.is_configured():
            return {}
        text, _sha = log_persist.read_file("logs/discord_schedule.json")
        if not text:
            return {}
        try:
            _settings_os.makedirs(
                _settings_os.path.dirname(_DISCORD_SCHEDULE_PATH),
                exist_ok=True)
            with open(_DISCORD_SCHEDULE_PATH, "w") as f:
                f.write(text)
        except Exception:
            pass
        return json.loads(text)
    except Exception:
        return {}


def _compute_today_dispatch_schedule():
    """Build today's dispatch state. v2 uses three FIXED CT slate post
    times (7 AM / 12:30 PM / 6 PM) plus an EOD summary at 1 AM next
    day. No per-day recompute — the only thing we need from the board
    is the pick candidates when each slate fires."""
    import discord_bot as _db
    from datetime import time as _time
    _d = datetime.now(CENTRAL).date()

    def _at(hh, mm, next_day=False):
        base = _d
        if next_day:
            base = _d + timedelta(days=1)
        return datetime.combine(base, _time(hh, mm), CENTRAL).isoformat()

    slates = {}
    for s, (hh, mm) in _db._SLATE_POST_TIMES.items():
        slates[str(s)] = {
            "post_at_iso": _at(hh, mm),
            "sent":        False,
            "pick_ids":    [],
        }

    eod_h, eod_m, eod_next = _db._EOD_POST_TIME
    return {
        "version": 2,
        "date":    _d.isoformat(),
        "agenda": {
            # 12:15 AM CT today — one text message with the day's slate
            # times + EOD time so viewers know what to expect.
            "post_at_iso": _at(0, 15),
            "sent":        False,
        },
        "slates":  slates,
        "eod": {
            "post_at_iso": _at(eod_h, eod_m, next_day=eod_next),
            "sent":        False,
        },
    }



@app.route("/healthz")
def healthz():
    """Dispatcher health check for UptimeRobot. Returns 200 only when
    the Discord dispatcher has ticked within the last 15 minutes. If
    it hasn't — because UptimeRobot stopped pinging /cron/dispatch,
    the dispatch lock is stuck, or the instance never came back from
    spin-down — this returns 500 so UptimeRobot's keyword/HTTP-status
    monitor fires an SMS alert.

    Threshold is generous (15 min) because UptimeRobot's free plan
    pings every 5 min; three missed ticks before alerting rules out
    one-off network blips. Pass ?threshold=N to override (minutes)."""
    import json as _json
    import time as _tn
    try:
        threshold_min = int(request.args.get("threshold") or "15")
    except Exception:
        threshold_min = 15
    threshold_sec = max(60, threshold_min * 60)
    try:
        with open(_DISPATCH_HEARTBEAT_PATH) as _hf:
            hb = _json.load(_hf) or {}
    except Exception:
        hb = {}
    last_ts = float(hb.get("ts") or 0)
    age_sec = int(_tn.time() - last_ts) if last_ts else None
    ok = (age_sec is not None) and (age_sec <= threshold_sec)
    body = {
        "ok":                 ok,
        "last_tick_ct":       hb.get("now_ct"),
        "age_seconds":        age_sec,
        "threshold_seconds":  threshold_sec,
        "note": ("Returns HTTP 200 when the dispatcher ticked within "
                 "threshold_seconds, else HTTP 500. Point UptimeRobot "
                 "at this URL to get SMS alerts when the dispatcher "
                 "stalls — the /cron/dispatch ping itself still runs "
                 "every 5 min on its own schedule."),
    }
    return Response(_json.dumps(body, indent=2),
                    mimetype="application/json",
                    status=200 if ok else 500)


@app.route("/debug/blend-backtest")
def debug_blend_backtest():
    """Backtest: take EVERY graded pick from the last N days (default 90),
    re-apply the single-stage per-sport blend to each pick's fair_prob,
    re-compute ev_pct from the blended fair_prob, re-run the signal_score
    with the NEW threshold table (EV 2/4, prob floor 0.58), re-apply the
    current filter (Signal >= 3 + not model-only + 60-min pre-game
    membership), and aggregate W-L-P-units-ROI for the surviving set.
    Returns a plain-text comparison vs the OLD-filter record so you can
    see whether tightening the EV scale would have helped or hurt.

    Pass ?days=N to change the window (default 90). Pass ?min_signal=N
    to simulate alternate Signal floors (default 3). Pass ?min_ev=X to
    simulate alternate EV minimum thresholds (default 2.0)."""
    import plays_log as _pl
    import picks as _picks_mod
    try:
        days = int(request.args.get("days") or "90")
    except Exception:
        days = 90
    try:
        min_signal = int(request.args.get("min_signal") or "3")
    except Exception:
        min_signal = 3
    try:
        min_ev = float(request.args.get("min_ev") or "3.0")
    except Exception:
        min_ev = 3.0
    try:
        # Additional hit-rate filter: require mc_prob (raw model
        # conviction) >= min_prob. Default 0 = disabled. Useful for
        # building "high-conviction only" variants where volume
        # drops but hit rate climbs.
        min_prob = float(request.args.get("min_prob") or "0.0")
    except Exception:
        min_prob = 0.0
    try:
        # Decimal cap — restrict to picks with price <= max_dec.
        # Favorites hit more often. 0 = disabled.
        max_dec = float(request.args.get("max_dec") or "0.0")
    except Exception:
        max_dec = 0.0
    try:
        # Decimal floor — restrict to picks with price >= min_dec.
        # Combined with max_dec, defines a price band (e.g. 1.30-1.65
        # for whale-tier). 0 = disabled.
        min_dec = float(request.args.get("min_dec") or "0.0")
    except Exception:
        min_dec = 0.0
    # Whale mode: apply the plays_log._is_whale_pick definition exactly
    # (fp >= 0.72, decimal 1.30-1.65, signal >= 4, ev >= 1.5, no risk).
    # Overrides other filter params when set.
    whale = request.args.get("whale") in ("1", "true", "yes")
    if whale:
        min_signal = 4
        min_ev     = 1.5
        min_prob   = 0.72
        min_dec    = 1.30
        max_dec    = 1.65

    graded_by_date = _pl.grade_all(limit_dates=days) or {}

    # Helper: re-blend ONE pick and re-score it. Returns dict with:
    #   old_cleared  = did it clear the old filter (Signal 3+ on raw EV)
    #   new_cleared  = does it clear the new filter (Signal 3+ on blended EV)
    #   old_signal, new_signal
    #   old_ev, new_ev, blended_fair, result, profit_u
    def _rescore(p):
        if p.get("model_only"):
            return None
        if not p.get("passes_curfilter") and not p.get("strong"):
            # Pick wasn't in the recommended set within 60-min of game start
            # by either the old filter OR current snapshot, skip it (same
            # membership rule as the standing current-filter record).
            # Still let it through if it has signal_score >= 3 historically.
            pass
        pin = p.get("pinnacle_prob")
        sim = p.get("mc_prob")
        if sim is None:
            sim = p.get("fair_prob")
        try:
            dec = float(p.get("decimal") or 0.0)
        except (TypeError, ValueError):
            return None
        if dec <= 1.0:
            return None
        try:
            old_ev = float(p.get("ev_pct") or 0.0)
            old_fair = float(p.get("fair_prob") or 0.0)
        except (TypeError, ValueError):
            return None
        # Compute new blended fair_prob + ev
        if pin is None or sim is None:
            # Can't rebuild without both — treat as unchanged, which
            # means it keeps its old scoring.
            new_fair = old_fair
            new_ev = old_ev
        else:
            try:
                pin_f = float(pin)
                sim_f = float(sim)
            except (TypeError, ValueError):
                return None
            slug = (p.get("sport_slug") or (p.get("sport") or "")).lower()
            mw_sport = _picks_mod._SPORT_MODEL_WEIGHT.get(
                slug, _picks_mod.MODEL_WEIGHT)
            market_w = 1.0 - mw_sport
            new_fair = mw_sport * sim_f + market_w * pin_f
            try:
                push = float(p.get("push_prob") or 0.0)
            except (TypeError, ValueError):
                push = 0.0
            new_ev = (new_fair * dec - (1 - push)) * 100.0

        # OLD signal_score was EV 3/6 + 0.60 floor. Replicate.
        def _old_sig(fair, ev):
            s = 0
            if ev >= 6.0: s += 2
            elif ev >= 3.0: s += 1
            # line_move + book_agreement from stored fields
            try:
                mv = float(p.get("line_move_pp") or 0.0)
            except Exception: mv = 0.0
            if mv > 0: s += 1
            if p.get("kalshi_confirmed"):
                s += 1
            else:
                dk = p.get("dk_divergence_pp")
                k = p.get("kalshi_divergence_pp")
                try:
                    if (dk is not None and float(dk) > 0) or (k is not None and float(k) > 0):
                        s += 1
                except Exception: pass
            if fair >= 0.60 and p.get("source") != "alt": s += 1
            return min(5, max(0, s))

        # NEW signal_score — hybrid: use RAW-sim EV + raw mc_prob
        # (same thresholds as OLD) because the blend dampens the
        # exact signal that was predictive. See _apply_fair_prob_blend
        # comment for context. UI still shows blended fair_prob as
        # "Model X%" — just the FILTER uses raw-sim EV.
        _EV_HI = 6.0   # +2 bar
        _EV_LO = 3.0   # +1 bar
        _PROB_FLOOR = 0.60
        # Recompute raw-sim EV for backtest since it may not be stored
        # on historical picks (which pre-date this change).
        try:
            dec_f = float(p.get("decimal") or 0.0)
            push_f = float(p.get("push_prob") or 0.0)
            try:
                sim_f = float(sim)
            except (TypeError, ValueError):
                sim_f = 0.0
            raw_ev = (sim_f * dec_f - (1 - push_f)) * 100.0 if dec_f > 1 else 0.0
        except (TypeError, ValueError):
            raw_ev = 0.0
        try:
            raw_fair = float(sim) if sim is not None else 0.0
        except (TypeError, ValueError):
            raw_fair = 0.0

        def _new_sig(fair, ev):
            # Override `ev` and `fair` with the raw-sim values so the
            # backtest reflects the hybrid behavior exactly.
            ev = raw_ev
            fair = raw_fair
            s = 0
            if ev >= _EV_HI: s += 2
            elif ev >= _EV_LO: s += 1
            try:
                mv = float(p.get("line_move_pp") or 0.0)
            except Exception: mv = 0.0
            if mv > 0: s += 1
            if p.get("kalshi_confirmed"):
                s += 1
            else:
                dk = p.get("dk_divergence_pp")
                k = p.get("kalshi_divergence_pp")
                try:
                    if (dk is not None and float(dk) > 0) or (k is not None and float(k) > 0):
                        s += 1
                except Exception: pass
            if fair >= _PROB_FLOOR and p.get("source") != "alt": s += 1
            return min(5, max(0, s))

        old_s = _old_sig(old_fair, old_ev)
        new_s = _new_sig(new_fair, new_ev)
        return {
            "old_sig": old_s, "new_sig": new_s,
            "old_ev":  old_ev, "new_ev": new_ev,
            "old_fair": old_fair, "new_fair": new_fair,
            "old_cleared": old_s >= 3 and p.get("passes_curfilter", False),
            "new_cleared": (
                new_s >= min_signal
                and raw_ev >= min_ev
                and raw_fair >= min_prob
                and (max_dec <= 0 or dec <= max_dec)
                and (min_dec <= 0 or dec >= min_dec)
            ),
            "result": p.get("result"),
            "profit_u": p.get("profit_u") or 0.0,
            "ev_delta_pct": new_ev - old_ev,
            "fair_delta_pp": (new_fair - old_fair) * 100,
        }

    old_set = []   # picks that cleared the OLD filter
    new_set = []   # picks that would clear the NEW filter
    both_set = [] # intersection
    only_new = [] # new-only (would have been added)
    only_old = [] # old-only (would have been dropped)

    for date, picks in sorted(graded_by_date.items()):
        for p in picks:
            r = _rescore(p)
            if r is None:
                continue
            if r["old_cleared"] and r["result"] in ("W", "L", "P"):
                old_set.append(r)
            if r["new_cleared"] and r["result"] in ("W", "L", "P"):
                new_set.append(r)
            if r["old_cleared"] and r["new_cleared"]:
                both_set.append(r)
            elif r["new_cleared"] and not r["old_cleared"]:
                only_new.append(r)
            elif r["old_cleared"] and not r["new_cleared"]:
                only_old.append(r)

    def _agg(rows):
        w = sum(1 for r in rows if r["result"] == "W")
        l = sum(1 for r in rows if r["result"] == "L")
        pu = sum(1 for r in rows if r["result"] == "P")
        settled = w + l + pu
        units = sum(float(r.get("profit_u") or 0.0) for r in rows)
        risked = settled   # 1 unit per pick is the standing assumption
        return {
            "n": len(rows), "W": w, "L": l, "P": pu, "settled": settled,
            "hit_pct": (100.0 * w / settled) if settled else 0.0,
            "units": round(units, 2),
            "roi_pct": (100.0 * units / risked) if risked else 0.0,
        }

    old_agg  = _agg(old_set)
    new_agg  = _agg(new_set)
    both_agg = _agg(both_set)
    gained   = _agg(only_new)
    dropped  = _agg(only_old)

    out = []
    out.append("=" * 76)
    out.append(f"  BLEND BACKTEST — last {days} days of graded picks")
    out.append("=" * 76)
    out.append(f"  Simulating new filter at Signal >= {min_signal}  EV >= {min_ev:.1f}%  prob floor 0.58")
    out.append("")
    out.append("                       picks   W-L-P    hit%    units     ROI%")
    out.append("  " + "-" * 70)
    def _row(label, a):
        return (f"  {label:20s}  {a['n']:>4}   {a['W']:>2}-{a['L']:>2}-{a['P']:>2}  "
                f"{a['hit_pct']:>5.1f}%  {a['units']:>+7.2f}u  {a['roi_pct']:>+6.2f}%")
    out.append(_row("OLD filter (as-run)", old_agg))
    out.append(_row("NEW filter (sim)",    new_agg))
    out.append("")
    out.append(f"  Kept by BOTH filters:     {_row('', both_agg).strip()}")
    out.append(f"  DROPPED (old had, new -): {_row('', dropped).strip()}")
    out.append(f"  GAINED  (new has, old -): {_row('', gained).strip()}")
    out.append("")
    if dropped["n"] > 0:
        out.append(f"  Dropped set ROI {dropped['roi_pct']:+.2f}%  → if positive, we LOST profitable picks.")
        out.append(f"                            → if negative, we DROPPED losers (good).")
    if gained["n"] > 0:
        out.append(f"  Gained set ROI {gained['roi_pct']:+.2f}%  → if positive, we ADDED winners (good).")
        out.append(f"                            → if negative, we added losers.")
    out.append("")
    out.append("  INTERPRETATION:")
    net_vs = new_agg["units"] - old_agg["units"]
    out.append(f"    Net units delta (NEW − OLD): {net_vs:+.2f}u")
    out.append(f"    Pick-volume delta: {new_agg['n'] - old_agg['n']:+d}")
    if net_vs >= 0 and new_agg["n"] <= old_agg["n"]:
        out.append("    → New filter is a strict improvement (more units, fewer bets).")
    elif net_vs >= 0:
        out.append("    → New filter is net-positive — more units, maybe more picks.")
    elif new_agg["n"] <= old_agg["n"] * 0.7:
        out.append("    → New filter is tighter but net-negative in units — may be too strict.")
    else:
        out.append("    → New filter is net-negative in units — consider reverting or re-tuning.")
    out.append("")
    out.append(f"  Query params:  ?days=N  ?min_signal=N  ?min_ev=X")
    out.append("  Example:  /debug/blend-backtest?days=30&min_ev=1.5")
    out.append("")
    return Response("\n".join(out), mimetype="text/plain")


@app.route("/debug/dispatch")
def debug_dispatch():
    """Human-readable ops dashboard for the Discord dispatcher. Shows:
    today's schedule state (agenda / 3 slates / EOD) with sent-flag,
    attempts, last-result, and queued post times; whether UptimeRobot
    appears to still be pinging (last-dispatch-tick age); the win
    alerts already fired today; and the current webhook probe status.
    One glance tells you if everything's healthy without parsing JSON.
    """
    import json as _json
    settings = _load_settings()
    webhook  = (settings.get("daily_picks_webhook_url") or "").strip()
    now_ct   = datetime.now(CENTRAL)
    today    = now_ct.date().isoformat()

    # Load current schedule state. The local file lives on Render's
    # ephemeral FS and can disappear on spin-down; `_load_dispatch_
    # schedule_remote_fallback` reads the GitHub mirror. Prefer the
    # local file when it exists and matches today's date — otherwise
    # fall back to the mirror so this page reflects reality instead
    # of showing an empty schedule the live dispatcher clearly has.
    sched = {}
    try:
        sched = _load_dispatch_schedule() or {}
    except Exception:
        pass
    if sched.get("date") != today:
        try:
            remote = _load_dispatch_schedule_remote_fallback() or {}
            if remote.get("date") == today:
                sched = remote
        except Exception:
            pass
    prior = {}
    try:
        prior = _load_prior_dispatch_schedule() or {}
    except Exception:
        pass

    # Win-alerts already sent today
    win_ids = []
    try:
        import discord_bot as _db
        win_ids = sorted(_db._load_result_sent() or [])
    except Exception:
        pass

    # Fired events (dedup file)
    fired = {}
    try:
        import log_persist
        text, _sha = log_persist.read_file("logs/discord_fired_events.json")
        if text:
            fired = _json.loads(text) or {}
    except Exception:
        try:
            with open(_DISCORD_FIRED_PATH) as f:
                fired = _json.load(f) or {}
        except Exception:
            pass
    fired_today = sorted(k for k in fired.keys() if k.startswith(today))

    def _row(label, meta):
        """Pretty-print one slate row."""
        if not meta:
            return f"  {label}: (not in schedule)"
        sent = meta.get("sent")
        pat  = meta.get("post_at_iso") or "?"
        att  = meta.get("attempts")
        pids = meta.get("pick_ids") or []
        last = meta.get("last_result") or {}
        bits = [f"  {label}:",
                f"sent={'YES' if sent else 'no '}",
                f"at={pat}",
                f"picks={len(pids)}"]
        if att:
            bits.append(f"attempts={att}")
        if last:
            bits.append(f"last=sent:{last.get('sent')}" +
                        (f" err:{last['error']}" if last.get('error') else "") +
                        (f" picks:{last['picks']}" if last.get('picks') is not None else ""))
        return "  ".join(bits)

    slates = sched.get("slates") or {}
    agenda = sched.get("agenda") or {}
    eod    = sched.get("eod") or {}

    lines = []
    lines.append("=" * 70)
    lines.append(f"  DISCORD DISPATCHER — ops view")
    lines.append("=" * 70)
    lines.append(f"  Now (CT):     {now_ct.isoformat()}")
    lines.append(f"  Today:        {today}")
    lines.append(f"  Webhook:      {'configured (…' + webhook[-20:] + ')' if webhook else 'MISSING — set in /settings'}")
    # Rate-limit cooldown (shared across every send_* call in
    # discord_bot). When a Cloudflare 1015 or Discord 429 hits, all
    # sends are suspended for 15 min so the limit window doesn't keep
    # extending.
    try:
        import discord_bot as _dbmod
        _cd = _dbmod.rate_limit_remaining_sec()
        if _cd > 0:
            lines.append(f"  RATE LIMIT:   active — {_cd}s remaining before sends resume")
    except Exception:
        pass
    _sched_date = sched.get("date")
    if _sched_date and _sched_date != today:
        lines.append("")
        lines.append(f"  !! WARNING: schedule date is {_sched_date}, not {today}.")
        lines.append(f"     Hit /cron/dispatch to force recompute (or wait for next UptimeRobot tick).")
    elif not _sched_date:
        lines.append("")
        lines.append(f"  !! WARNING: no schedule loaded (local and mirror both empty).")
        lines.append(f"     Hit /cron/dispatch to initialize today's schedule.")
    lines.append("")
    lines.append("  TODAY'S SCHEDULE")
    lines.append("  " + "-" * 66)
    lines.append(_row("Agenda  ", agenda))
    for s in ("1", "2", "3"):
        lines.append(_row(f"Slate {s} ", slates.get(s)))
    lines.append(_row("EOD     ", eod))
    lines.append("")
    lines.append(f"  Fired dedup markers today ({len(fired_today)}):")
    for k in fired_today:
        lines.append(f"    {k}")
    lines.append("")
    lines.append(f"  Win alerts posted today ({len(win_ids)}):")
    for pid in win_ids:
        lines.append(f"    {pid}")
    lines.append("")
    with _DISPATCH_ERROR_LOCK:
        _errs = list(_DISPATCH_ERRORS)
    if _errs:
        lines.append(f"  Dispatcher errors (last {len(_errs)}):")
        for e in _errs:
            lines.append(f"    {e['ts']}  {e['context']}: {e['error']}")
        lines.append("")
    if prior:
        lines.append("  PRIOR DAY (archived)")
        lines.append("  " + "-" * 66)
        lines.append(f"  Date: {prior.get('date')}")
        _p_slates = prior.get("slates") or {}
        _p_eod    = prior.get("eod") or {}
        for s, meta in sorted(_p_slates.items()):
            lines.append(_row(f"Slate {s} ", meta))
        lines.append(_row("EOD     ", _p_eod))
        lines.append("")
    lines.append("  QUICK ACTIONS")
    lines.append("  " + "-" * 66)
    lines.append("  Probe webhook:        /debug/discord?test=1")
    lines.append("  Force send slate N:   /cron/send-slate?s=1  (or 2 / 3)")
    lines.append("  Force dispatcher:     /cron/dispatch")
    lines.append("  Full JSON state:      /cron/dispatch  (raw)")
    lines.append("")
    return Response("\n".join(lines), mimetype="text/plain")


@app.route("/debug/ai")
def debug_ai():
    """Probe Anthropic AI with the exact per-pick verdict pattern.
    Returns env-key presence, SDK version, raw response blocks, and
    the parsed verdict string. Use when the AI Picks section stays
    empty to see what the model is actually returning."""
    import json as _json
    import os as _os
    out = {
        "anthropic_api_key_present": bool(_os.environ.get("ANTHROPIC_API_KEY")),
        "settings_sync_key_present": bool(_os.environ.get("SETTINGS_SYNC_KEY")),
    }
    try:
        import anthropic as _ant
        out["sdk_version"] = getattr(_ant, "__version__", "?")
    except Exception as e:
        out["sdk_version_error"] = f"{type(e).__name__}: {e}"
        return Response(_json.dumps(out, indent=2), mimetype="application/json")
    if not out["anthropic_api_key_present"]:
        return Response(_json.dumps(out, indent=2), mimetype="application/json")
    try:
        client = _ant.Anthropic(api_key=_os.environ["ANTHROPIC_API_KEY"])
        prompt = (
            "You are a sharp sports betting analyst. One pick to evaluate:\n"
            "Sport: NHL\nGame: Dallas Stars at Winnipeg Jets\n"
            "Market: Team Total\nPick: Over 2.5 @ 1.95 (Pinnacle)\n"
            "Model prob: 55.3%  Pinnacle devig: 51.2%\n"
            "EV: +8.2%  Signal composite: 3/5\n\n"
            "Reply with ONE of these verdicts followed by one short reason "
            "(<=15 words):\n"
            "  STRONG TAKE  — exceptional edge, no concerns\n"
            "  LEAN         — real edge, standard confidence\n"
            "  PASS         — thin edge or specific red flag, skip\n"
            "  AVOID        — clear reason this pick won't hit\n"
            "\n"
            "Format: VERDICT: <reason>"
        )
        resp = client.messages.create(
            model="claude-sonnet-5-5",
            max_tokens=2048,
            system=(
                "You are a sharp sports betting analyst. Reply ONLY "
                "with the verdict word followed by a short reason, in "
                "the exact format the user requests. Do not add "
                "preamble or caveats."
            ),
            messages=[{"role": "user", "content": prompt}],
        )
        blocks = []
        for b in (resp.content or []):
            blocks.append({
                "type": getattr(b, "type", None),
                "text": (getattr(b, "text", "") or "")[:300],
                "has_text_attr": hasattr(b, "text"),
            })
        out["model"] = "claude-sonnet-5-5"
        out["stop_reason"] = getattr(resp, "stop_reason", None)
        out["blocks"] = blocks
        out["usage"] = {
            "input": getattr(getattr(resp, "usage", None), "input_tokens", None),
            "output": getattr(getattr(resp, "usage", None), "output_tokens", None),
        }
    except Exception as e:
        out["api_error"] = f"{type(e).__name__}: {e}"
    # Also exercise the full background-thread flow with a dummy pick so
    # we can confirm _queue_ai_verdict_fill actually writes to cache.
    # We clean up the debug-probe entry after the test so it doesn't
    # linger in the cache and skew analytics (the previous version
    # polluted the cache with debug-probe-{ts} entries that showed up
    # in the AI tier counts as Lean verdicts).
    try:
        import time as _tm
        dummy_pid = f"debug-probe-{int(_tm.time())}"
        dummy_pick = {
            "id":            dummy_pid,
            "sport_name":    "NHL",
            "away_team":     "Dallas Stars",
            "home_team":     "Winnipeg Jets",
            "market":        "Team Total",
            "pick":          "Over 2.5",
            "decimal":       1.95,
            "book":          "Pinnacle",
            "mc_prob":       0.553,
            "pinnacle_prob": 0.512,
            "ev_pct":        8.2,
            "signal_score":  3,
        }
        pre_cache = _load_ai_verdict_cache()
        pre_count = len(pre_cache)
        _queue_ai_verdict_fill(dummy_pick)
        import time as _tm2
        deadline = _tm2.time() + 30
        got = None
        while _tm2.time() < deadline:
            _tm2.sleep(1)
            cache = _load_ai_verdict_cache()
            if dummy_pid in cache:
                got = cache[dummy_pid]
                break
        # Clean up the probe entry so it doesn't pollute the cache
        # (also sweep any older debug-probe-* entries left from
        # previous probe runs — one-time cleanup, idempotent).
        try:
            cache = _load_ai_verdict_cache()
            removed = 0
            for stale_pid in [k for k in list(cache.keys())
                              if isinstance(k, str) and k.startswith("debug-probe-")]:
                del cache[stale_pid]
                removed += 1
            if removed:
                _save_ai_verdict_cache(cache)
        except Exception:
            removed = -1
        out["bg_thread_test"] = {
            "pre_cache_size": pre_count,
            "post_cache_size": len(_load_ai_verdict_cache()),
            "dummy_pid":       dummy_pid,
            "wrote_entry":     got is not None,
            "entry":           got,
            "waited_sec":      30 - int(deadline - _tm2.time()),
            "probe_cleanup":   removed,
        }
    except Exception as e:
        out["bg_thread_test_error"] = f"{type(e).__name__}: {e}"
    out["counters"] = dict(_AI_COUNTERS)
    out["inflight_count"] = len(_AI_INFLIGHT)
    return Response(_json.dumps(out, indent=2), mimetype="application/json")


@app.route("/debug/nba-backtest")
def debug_nba_backtest():
    """Run the NBA walk-forward Elo + pace fit from ESPN scoreboards.
    Pass ?days=N (default 365) to control the window. Returns JSON
    with games processed, metric summary (log-loss, Brier, margin
    MAE, total MAE), and the top-10 teams by Elo. Writes the per-
    team ratings to logs/nba_ratings_cache.json and mirrors via
    log_persist so simulate_game() picks them up on the next render.
    Takes a while — fetching 365 days of ESPN scoreboards is ~365
    HTTP calls. Expect 2-5 min on first run."""
    import json as _json
    try:
        days = int(request.args.get("days") or "365")
    except Exception:
        days = 365
    days = max(7, min(days, 1095))  # clamp 1 week to 3 years
    try:
        import nba_backtest as _nbt
        result = _nbt.run_backtest(days_back=days, verbose=False)
    except Exception as e:
        return Response(_json.dumps({"ok": False,
                                       "error": f"{type(e).__name__}: {e}"}),
                        status=500, mimetype="application/json")
    return Response(_json.dumps({"ok": True, **result}, indent=2),
                    mimetype="application/json")


@app.route("/debug/discord")
def debug_discord():
    """Probe the configured Discord webhook with a tiny test post.
    Returns {ok, http_code, body, webhook_tail}. Use when slates say
    sent=True but nothing lands in Discord — this will show if the
    webhook has been rotated/deleted (401/404), rate-limited (429), or
    is actually healthy (204)."""
    import json as _json
    from urllib.request import Request as _Req, urlopen as _uo
    from urllib.error import HTTPError as _HE
    settings = _load_settings()
    # Match moderator's resolution order: dedicated picks webhook first,
    # fall back to the general discord_webhook_url so single-channel
    # users don't need to configure two fields.
    url = (settings.get("daily_picks_webhook_url") or "").strip()
    source = "daily_picks_webhook_url"
    if not url:
        url = (settings.get("discord_webhook_url") or "").strip()
        source = "discord_webhook_url (fallback)" if url else ""
    if not url:
        return Response(_json.dumps({"ok": False, "error": "no_webhook_configured"}),
                        mimetype="application/json")
    tail = url[-24:] if len(url) > 24 else url
    test_mode = request.args.get("test") not in ("", None, "0", "false")
    if not test_mode:
        return Response(_json.dumps({
            "ok": True,
            "webhook_configured": True,
            "webhook_tail": "…" + tail,
            "source": source,
            "note": "Pass ?test=1 to send a one-line probe message to the webhook."
        }, indent=2), mimetype="application/json")
    body = _json.dumps({"content": "cheeks-model probe — ignore"}).encode()
    req = _Req(url, data=body, method="POST", headers={
        "Content-Type": "application/json",
        "User-Agent":   "cheeks-model/1.0 (+https://cheeks-model.onrender.com)",
    })
    try:
        with _uo(req, timeout=15) as r:
            code = r.status
            resp_body = r.read().decode("utf-8", errors="replace")[:500]
        out = {"ok": True, "http_code": code, "body": resp_body,
               "webhook_tail": "…" + tail}
    except _HE as e:
        try:
            resp_body = e.read().decode("utf-8", errors="replace")[:500]
        except Exception:
            resp_body = ""
        out = {"ok": False, "http_code": e.code, "body": resp_body,
               "webhook_tail": "…" + tail}
    except Exception as e:
        out = {"ok": False, "http_code": 0, "error": type(e).__name__ + ": " + str(e),
               "webhook_tail": "…" + tail}
    return Response(_json.dumps(out, indent=2), mimetype="application/json")


@app.route("/cron/send-slate")
def cron_send_slate():
    """Force-send one slate PNG right now, bypassing the dispatcher's
    sent-state. Pass ?s=1|2|3. Also resets that slate's local sent flag
    so future dispatcher ticks don't short-circuit. Returns the raw
    _send_slate_png result so success/failure is visible."""
    import json as _json
    try:
        s = int(request.args.get("s") or "1")
    except Exception:
        s = 1
    if s not in (1, 2, 3):
        return Response(_json.dumps({"ok": False, "error": "s must be 1,2,3"}),
                        mimetype="application/json", status=400)
    r = _send_slate_png(s)
    # If the manual send succeeded, mark local state as sent so the
    # dispatcher doesn't try to post again on its next tick.
    try:
        if r.get("sent"):
            import log_persist
            try:
                text, _sha = log_persist.read_file("logs/discord_schedule.json")
                sched = _json.loads(text) if text else {}
            except Exception:
                sched = {}
            today = datetime.now(CENTRAL).date().isoformat()
            if sched.get("date") == today:
                slates = sched.get("slates") or {}
                meta = slates.get(str(s)) or {}
                meta["sent"] = True
                meta["pick_ids"] = r.get("pick_ids") or meta.get("pick_ids") or []
                slates[str(s)] = meta
                sched["slates"] = slates
                try:
                    log_persist.write_file("logs/discord_schedule.json",
                                           _json.dumps(sched, indent=2))
                except Exception:
                    pass
                try:
                    _mark_fired(f"{today}:slate{s}")
                except Exception:
                    pass
    except Exception:
        pass
    return Response(_json.dumps({"ok": True, "slate": s, "result": r}, indent=2),
                    mimetype="application/json")


