@app.route("/discord/dedup-sweep")
def discord_dedup_sweep():
    """Scan the Discord channel's recent history and delete any
    duplicate posts (same content prefix). Keeps the OLDEST message
    in each duplicate group. Requires a bot token with Manage
    Messages. Pass ?dry=1 to see what WOULD be deleted without
    actually deleting."""
    import json as _json
    s = _load_settings()
    hook = _resolve_discord_webhook_mlb(s)
    bot  = (s.get("discord_bot_token") or "").strip()
    if not hook:
        return Response(_json.dumps({"ok": False,
                                       "error": "no webhook configured"}),
                        status=400, mimetype="application/json")
    if not bot:
        return Response(_json.dumps({"ok": False,
                                       "error": "no bot token — add discord_bot_token in /settings"}),
                        status=400, mimetype="application/json")
    try:
        import discord_bot
        channel_id = discord_bot._channel_id_from_webhook(hook)
        if not channel_id:
            return Response(_json.dumps({"ok": False,
                                           "error": "could not resolve channel_id from webhook"}),
                            status=500, mimetype="application/json")
        dry = (request.args.get("dry") or "") in ("1", "true", "yes")
        out = discord_bot.delete_duplicate_messages(bot, channel_id,
                                                     scan_limit=100,
                                                     dry_run=dry)
        return Response(_json.dumps(out, indent=2),
                        mimetype="application/json")
    except Exception as e:
        return Response(_json.dumps({"ok": False,
                                       "error": f"{type(e).__name__}: {e}"}),
                        status=500, mimetype="application/json")


def _resolve_discord_webhook_mlb(settings):
    """Local copy of agents._resolve_discord_webhook so routes in
    mlb_ui don't have to round-trip through the agents module just
    for a webhook lookup."""
    url = (settings.get("daily_picks_webhook_url") or "").strip()
    if url:
        return url
    return (settings.get("discord_webhook_url") or "").strip()


@app.route("/debug/live-scores")
def debug_live_scores():
    """Diagnose the live-score backfill. Pass ?sport=<slug> to limit.
    Returns per-sport fetch counts, matched/unmatched games, and the
    team-name tokens being compared. Also dumps the contents of
    logs/live_scores.json (written by Agent #9) so we can tell if
    the file-based path has fresh data."""
    import json as _json
    # Also dump the shared file written by Agent #9's live grader
    _lv_file_state = {}
    try:
        import os as _os_dbg
        _lv_path = _os_dbg.path.join(_os_dbg.path.dirname(_os_dbg.path.abspath(__file__)),
                                       "logs", "live_scores.json")
        try:
            with open(_lv_path) as _lf:
                _lv_file_state = _json.load(_lf) or {}
        except FileNotFoundError:
            _lv_file_state = {"error": "file does not exist"}
        except Exception as _le:
            _lv_file_state = {"error": f"{type(_le).__name__}: {_le}"}
    except Exception:
        pass
    sport_slug = (request.args.get("sport") or "").strip().lower() or None
    try:
        today = datetime.now(CENTRAL).date()
        board, _ = _build_board_rows(today.isoformat(), today, "all",
                                      strong_only=False)
    except Exception as e:
        return Response(_json.dumps({"ok": False, "error": f"board build: {e}"}),
                        status=500, mimetype="application/json")
    import plays_log as _pl
    import sports as _sp
    def _toks(name):
        n = (name or "").lower().strip()
        if not n: return []
        t = {n}
        for w in n.split():
            if len(w) >= 4: t.add(w)
        return sorted(t)
    out_sports = {}
    for sport_cfg in _sp.SPORTS:
        slug = sport_cfg["slug"]
        if sport_slug and slug != sport_slug:
            continue
        rows_for_sport = [r for r in board if r.get("sport_slug") == slug
                          and (r.get("status") or "") in ("live", "final")]
        if not rows_for_sport:
            continue
        espn_path = sport_cfg.get("espn_scoreboard")
        try:
            events = _pl.fetch_scores_espn(espn_path, days_back=1, ref_date=today)
        except Exception as e:
            events = []
            out_sports[slug] = {"error": str(e)}
            continue
        ev_names = []
        for ev in events:
            scores = ev.get("scores") or []
            ht = ev.get("home_team") or ""
            at = ev.get("away_team") or ""
            if ht and at and len(scores) >= 2:
                ev_names.append({
                    "home": ht,
                    "away": at,
                    "home_score": scores[0].get("score"),
                    "away_score": scores[1].get("score"),
                })
        # Also run the actual matcher inline so we can see per-row
        # what hits/misses.
        _ev_by_token = {}
        for _ev in events:
            _ht = _ev.get("home_team") or ""
            _at = _ev.get("away_team") or ""
            scores = _ev.get("scores") or []
            if not _ht or not _at or len(scores) < 2:
                continue
            for t in _toks(_ht):
                _ev_by_token.setdefault(t, []).append(("home", _at, _ht))
            for t in _toks(_at):
                _ev_by_token.setdefault(t, []).append(("away", _ht, _at))
        row_matches = []
        for r in rows_for_sport[:8]:
            hts = _toks(r.get("home"))
            ats = _toks(r.get("away"))
            match = None
            for tok in hts:
                cands = _ev_by_token.get(tok) or []
                for role, opp, me in cands:
                    opp_toks = _toks(opp)
                    if any(t in opp_toks for t in ats):
                        match = {"matched_via_token": tok,
                                 "espn_home_or_away": role,
                                 "espn_opp": opp,
                                 "espn_me": me}
                        break
                if match:
                    break
            row_matches.append({
                "row": f"{r.get('away')} @ {r.get('home')}",
                "match": match,
            })
        out_sports[slug] = {
            "espn_path": espn_path,
            "events_fetched": len(events),
            "espn_events": ev_names[:8],
            "board_rows": [{
                "home": r.get("home"),
                "away": r.get("away"),
                "status": r.get("status"),
                "score_home": r.get("score_home"),
                "score_away": r.get("score_away"),
                "home_tokens": _toks(r.get("home")),
                "away_tokens": _toks(r.get("away")),
            } for r in rows_for_sport[:8]],
            "row_matches": row_matches,
        }
    return Response(_json.dumps({"ok": True,
                                   "sports": out_sports,
                                   "live_scores_file": _lv_file_state},
                                 indent=2),
                    mimetype="application/json")


@app.route("/pick/force-post")
def pick_force_post():
    """Manual trigger: post one specific pick to Discord right now,
    bypassing the evidence-score bar and the pre-game window gate.
    Still records the pick in the moderator's dedup log so it isn't
    double-posted later on a normal tick.

    Usage: /pick/force-post?id=<pick_id>  (gets the pick id from the
    moderator-tick diagnostic or the dashboard)."""
    import json as _json
    pid = (request.args.get("id") or "").strip()
    if not pid:
        return Response(_json.dumps({"ok": False, "error": "?id= required"}),
                        status=400, mimetype="application/json")
    try:
        today = datetime.now(CENTRAL).date()
        board, _ = _build_board_rows(today.isoformat(), today, "all",
                                      strong_only=False)
        found = None
        for row in board:
            for p in (row.get("picks") or []):
                if p.get("id") == pid:
                    p["home_team"]   = p.get("home_team")   or row.get("home")
                    p["away_team"]   = p.get("away_team")   or row.get("away")
                    p["sport_slug"]  = p.get("sport_slug")  or row.get("sport_slug")
                    p["sport_name"]  = p.get("sport_name")  or row.get("sport_name")
                    p["start_time"]  = p.get("start_time")  or row.get("game_start_iso")
                    found = p
                    break
            if found:
                break
        if not found:
            return Response(_json.dumps({"ok": False,
                                           "error": "pick not found on today's board"}),
                            status=404, mimetype="application/json")
        import agents
        # Default is idempotent — refuses if the pick was already
        # posted today. Pass ?replay=1 to force a repost (e.g. the
        # user wants an updated version re-sent after lineup news).
        allow_replay = (request.args.get("replay") or "") in ("1", "true", "yes")
        r = agents.post_individual_pick(found, allow_replay=allow_replay)
        return Response(_json.dumps(r, indent=2),
                        mimetype="application/json")
    except Exception as e:
        return Response(_json.dumps({"ok": False,
                                       "error": f"{type(e).__name__}: {e}"}),
                        status=500, mimetype="application/json")


@app.route("/discord/reintro", methods=["GET", "POST"])
def discord_reintro():
    """Nuke the Discord channel and post a fresh short intro.

    Deletes all prior messages if a bot token (`discord_bot_token`
    setting / `DISCORD_BOT_TOKEN` env) with Manage Messages in the
    channel is configured. Without a bot token the delete step is
    skipped — webhooks alone can't list channel history — and we
    just post the fresh intro. The response's `notes` field tells
    the caller exactly what did (or didn't) run.

    Also clears the moderator's per-pick dedup log so the fresh
    channel can repost today's picks when they next clear the
    evidence threshold inside their pre-game window.

    Triggered from the Settings page button, or by GET for cron."""
    import json as _json
    s = _load_settings()
    hook = (s.get("discord_webhook_url") or "").strip()
    bot = (s.get("discord_bot_token") or "").strip() or None
    if not hook:
        return Response(_json.dumps({"ok": False,
                                       "error": "no discord_webhook_url configured",
                                       "notes": ["Set the webhook URL in /settings first."]}),
                        status=400, mimetype="application/json")
    try:
        import discord_bot
        result = discord_bot.reset_channel_and_reintro(hook, bot_token=bot)
    except Exception as e:
        return Response(_json.dumps({"ok": False,
                                       "error": f"{type(e).__name__}: {e}"}),
                        status=500, mimetype="application/json")
    # Reset the moderator's dedup log so today's picks can repost
    # into the fresh channel next tick.
    try:
        import os as _os
        import json as _j
        _mod_dedup = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)),
                                     "logs", "discord_posted_individual.json")
        with open(_mod_dedup, "w") as f:
            _j.dump({}, f)
        result.setdefault("notes", []).append(
            "Moderator dedup log cleared — picks that still clear the "
            "evidence bar will repost on the next /cron/moderator-tick."
        )
    except Exception:
        pass
    # If called from the Settings form, redirect back with a flash
    # banner. Otherwise return JSON.
    if request.form.get("action") == "reset_discord":
        q = "ok" if result.get("ok") else "fail"
        return redirect(f"/settings?reset={q}")
    return Response(_json.dumps(result, indent=2),
                    mimetype="application/json")


