@app.route("/logged")
def logged_plays():
    """Dashboard of past picks with W/L records (7d / 30d / 90d, strong vs all).

    Also kicks off the daily deep analysis of logged picks (model_analytics)
    the first time it's hit each day — insights appear in-page and the picks
    pipeline reads back any recommended per-sport consensus weight shifts.
    """
    import plays_log, log_persist, model_analytics
    # Backfill: any date in the last 14 days with pending picks whose games
    # are >= 4h past start gets a forced re-grade. Catches picks the grader
    # couldn't settle on its first pass (ESPN returned empty, game hadn't
    # ended, etc.) so the records stop showing stale "pending" for ended
    # games. Non-fatal — the next step still runs even if this blows up.
    backfill_summary = None
    try:
        backfill_summary = plays_log.grade_pending_backfill(days_back=14)
    except Exception:
        backfill_summary = None
    try:
        graded_by_date = plays_log.grade_all(limit_dates=120)
    except Exception:
        graded_by_date = {}
    summary = plays_log.summary(graded_by_date)
    by_sport  = plays_log.breakdown_by_key(graded_by_date, lambda p: p.get("sport"))
    by_market = plays_log.breakdown_by_key(graded_by_date, lambda p: p.get("market"))
    # Signal-filter performance per sport — tells the user which models
    # are hitting under the current filter and which need weight tweaks.
    by_sport_curfilter = plays_log.breakdown_by_key_current_filter(
        graded_by_date, lambda p: p.get("sport"))
    dates = sorted(graded_by_date.keys(), reverse=True)

    # Phase 31 Round 3 H: calibration shrinkage recommendation per
    # sport, computed on the fly from last 30 days of graded picks.
    try:
        import pick_enhancers as _pe
        shrinkage_recs = _pe.compute_shrinkage_recs(graded_by_date, min_n=25)
    except Exception:
        shrinkage_recs = []

    # Phase 32: Kalshi portfolio tile — only if credentials are
    # configured. Non-fatal if the account has no fills or Kalshi is
    # unreachable.
    try:
        import kalshi_portfolio as _kp
        if _kp.is_configured():
            # days args ignored; the module uses RECORD_START_DATE
            # (currently 2026-08-18) as the fixed anchor.
            kalshi_summary = _kp.summarize_recent()
            kalshi_recent  = _kp.recent_settlements_table(limit=20)
            # Cross-check: aggregate the model's own graded units for
            # picks dated on/after the Kalshi anchor. Lets the user
            # compare "model would have made X u" vs "my Kalshi
            # account made Y dollars" over the same window — a quick
            # way to tell if the Kalshi losses are divergent from the
            # model (bets Kalshi made that the model wouldn't have, or
            # staking size issues) vs the model itself being wrong.
            try:
                _anchor = kalshi_summary.get("record_start") if kalshi_summary else None
                _units = 0.0
                _settled = 0
                _wins = 0
                if _anchor:
                    for _ds, _pks in (graded_by_date or {}).items():
                        if _ds < _anchor:
                            continue
                        for _pk in _pks:
                            if _pk.get("model_only"):
                                continue
                            if (_pk.get("signal_score") or 0) < 3:
                                continue
                            _r = _pk.get("result")
                            if _r not in ("W", "L", "P"):
                                continue
                            _settled += 1
                            if _r == "W":
                                _wins += 1
                            try:
                                _units += float(_pk.get("profit_u") or 0.0)
                            except (TypeError, ValueError):
                                pass
                if kalshi_summary is not None and _settled:
                    kalshi_summary["model_cross_units"]   = round(_units, 2)
                    kalshi_summary["model_cross_settled"] = _settled
                    kalshi_summary["model_cross_wins"]    = _wins
                    kalshi_summary["model_cross_hit_pct"] = round(100.0 * _wins / _settled, 1)
            except Exception:
                pass
        else:
            kalshi_summary = None
            kalshi_recent  = []
    except Exception:
        kalshi_summary = None
        kalshi_recent  = []

    # Discord-posted record summary — mirror of plays_log.summary's
    # curfilter_7d/30d/90d, filtered to pick ids that were actually
    # sent to the Discord channel's daily slates.
    def _dsummary():
        from datetime import timedelta as _td
        windows = {"discord_7d": 7, "discord_30d": 30, "discord_90d": 90}
        out = {}
        today_d = datetime.now(CENTRAL).date()
        posted = _load_discord_posted_log()
        for key, days in windows.items():
            w = l = pu = pend = 0
            units = 0.0
            risked = 0.0
            cutoff = today_d - _td(days=days)
            for ds, pids in posted.items():
                try:
                    d_dt = datetime.fromisoformat(ds).date()
                except Exception:
                    continue
                if d_dt < cutoff or d_dt > today_d:
                    continue
                picks_for_date = {p.get("id"): p for p in (graded_by_date.get(ds) or []) if p.get("id")}
                for pid in pids:
                    p = picks_for_date.get(pid)
                    if not p:
                        pend += 1
                        continue
                    r = p.get("result")
                    if r == "W":
                        w += 1
                    elif r == "L":
                        l += 1
                    elif r == "P":
                        pu += 1
                    else:
                        pend += 1
                        continue
                    try:
                        units += float(p.get("profit_u") or 0.0)
                    except (TypeError, ValueError):
                        pass
                    # 1 unit risked per pick is the convention plays_log uses
                    risked += 1.0
            settled = w + l + pu
            win_pct = (w / (w + l) * 100) if (w + l) else 0
            roi_pct = (units / risked * 100) if risked else 0
            out[key] = {
                "wins": w, "losses": l, "pushes": pu,
                "settled": settled, "pending": pend,
                "units": units, "risked": risked,
                "win_pct": win_pct, "roi_pct": roi_pct,
            }
        return out
    try:
        discord_summary = _dsummary()
    except Exception:
        discord_summary = {}

    # Per-filter 3-day pick lists — a focused mini-list rendered under
    # each record-tiles section. Replaces the old 'all picks by date'
    # mega-list. Each filter has its own predicate; the mini-list pulls
    # picks from the last 3 CALENDAR days (today + 2 priors) that match
    # the predicate, newest first.
    def _is_whale_pick(pk):
        # Mirror the tightened plays_log._is_whale_pick definition —
        # fp >= 68%, dec <= 1.60, EV >= 0, and (EV >= 3% OR Signal >= 2).
        return plays_log._is_whale_pick(pk)
    # Inject date onto each pick so predicates that need date context
    # (like Discord-posted, which looks picks up in a per-day map) can
    # read it off the pick dict. Idempotent — safe to repeat.
    for _ds, _picks in (graded_by_date or {}).items():
        for _p in (_picks or []):
            if _p.get("_date") != _ds:
                _p["_date"] = _ds

    # Pruned to the whole-picture filters: all, signal, strong,
    # current filter, Discord posted, +EV. Removed source-specific
    # tags (1H Goals, AI Analysis, DK history) that only cover their
    # own narrow pipeline and don't aggregate as a complete record.
    _FILTER_PREDICATES = {
        "all":        ("All picks",             lambda p: True),
        "signal":     ("Signal >= 3",           lambda p: plays_log._backtest_signal_score(p) >= 3),
        "whale":      ("Whale picks",            _is_whale_pick),
        "curfilter":  ("Current filter",        plays_log._passes_current_filter),
        "discord":    ("Discord posted",        _passes_discord_posted),
        "ev9":        ("+EV >= 9%",             lambda p: (p.get("ev_pct") is not None
                                                           and (p.get("ev_pct") or 0) >= 9)),
    }

    def _last_3d_picks(predicate):
        """Return a date -> [picks] dict for the last 3 calendar days
        (today + 2 priors), only picks matching the predicate.
        Each pick is enriched with its source date for the template."""
        from datetime import timedelta as _td
        today_d = datetime.now(CENTRAL).date()
        want_dates = [(today_d - _td(days=i)).isoformat() for i in range(3)]
        out = {}
        for ds in want_dates:
            picks = graded_by_date.get(ds) or []
            matches = [p for p in picks if predicate(p)]
            if matches:
                out[ds] = matches
        return out

    recent_by_filter = {
        key: _last_3d_picks(pred) for key, (_lbl, pred) in _FILTER_PREDICATES.items()
    }

    # Search form at bottom: date + filter. On submit, re-render with
    # the matching picks shown in the dedicated search-results block.
    search_date   = (request.args.get("search_date") or "").strip()
    search_filter = (request.args.get("search_filter") or "all").lower()
    if search_filter not in _FILTER_PREDICATES:
        search_filter = "all"
    search_results = []
    search_record  = None
    search_filter_label = _FILTER_PREDICATES[search_filter][0]
    if search_date:
        _pred = _FILTER_PREDICATES[search_filter][1]
        day_picks = graded_by_date.get(search_date) or []
        search_results = [p for p in day_picks if _pred(p)]
        w = l = p_ = pending = 0
        units = 0.0
        for pk in search_results:
            r = pk.get("result")
            if r == "W":   w += 1
            elif r == "L": l += 1
            elif r == "P": p_ += 1
            else:          pending += 1
            units += pk.get("profit_u", 0) or 0
        settled = w + l
        search_record = {
            "wins": w, "losses": l, "pushes": p_, "pending": pending,
            "settled": settled,
            "win_pct": (w / settled * 100) if settled else 0.0,
            "roi_pct": (units / settled * 100) if settled else 0.0,
            "units":   units,
        }
    filter_options = [{"key": k, "label": v[0]} for k, v in _FILTER_PREDICATES.items()]
    try:
        persist_status = log_persist.status_summary()
    except Exception as e:
        persist_status = {"enabled": False, "reason": f"status check failed: {e}"}
    try:
        anchor_status = plays_log.anchor_status_today()
    except Exception:
        anchor_status = {"buckets": ["00:00","03:00","11:00","16:00"],
                         "fired_today": [], "next_bucket": "00:00",
                         "next_in_min": 0, "anchored_total": 0,
                         "anchored_passed": 0}
    try:
        grader_status = plays_log.grader_status()
    except Exception:
        grader_status = {"odds_api_enabled": False, "mlb_statsapi": True}
    try:
        import generic_odds
        odds_usage = generic_odds.odds_api_usage_summary()
    except Exception:
        odds_usage = None
    # Polymarket history was removed from /logged — kept the import path
    # intact in case anything else still consumes it, but no longer passed
    # to the template.
    poly_summary = None

    # Phase 29 (3): 30-day daily P&L sparkline. One bar per day,
    # height proportional to units gained/lost that day.
    from datetime import date as _date, timedelta as _td
    pnl_bars = []
    try:
        today_d = _date.today()
        for i in range(29, -1, -1):
            d = today_d - _td(days=i)
            ds = d.isoformat()
            picks = graded_by_date.get(ds) or []
            units = 0.0
            n = 0
            for pk in picks:
                if pk.get("result") in ("W", "L", "P"):
                    units += float(pk.get("profit_u") or 0.0)
                    n += 1
            pnl_bars.append({"date": ds, "units": units, "n": n,
                             "label": d.strftime("%b %-d") if hasattr(d, "strftime") else ds})
    except Exception:
        # Windows strftime %-d fallback
        pnl_bars = []
        try:
            today_d = _date.today()
            for i in range(29, -1, -1):
                d = today_d - _td(days=i)
                ds = d.isoformat()
                picks = graded_by_date.get(ds) or []
                units = sum(float(p.get("profit_u") or 0.0) for p in picks if p.get("result") in ("W","L","P"))
                n = sum(1 for p in picks if p.get("result") in ("W","L","P"))
                pnl_bars.append({"date": ds, "units": units, "n": n,
                                 "label": d.strftime("%b %d").lstrip("0").replace(" 0", " ")})
        except Exception:
            pnl_bars = []

    # Phase 29 (8): calibration chart — all picks and current-filter
    # picks side by side. Bucket by predicted fair_prob (5% bins from
    # 45% to 90%), compare expected vs actual hit rate. Positive gap
    # (actual > expected) = model is sandbagging; negative = overconfident.
    # Points above the 45° line are good.
    def _calibration_bins(picks_iter):
        bins = {}
        for pk in picks_iter:
            if pk.get("result") not in ("W", "L"):
                continue
            fp = pk.get("fair_prob")
            if fp is None:
                continue
            try: fp = float(fp)
            except (TypeError, ValueError): continue
            if not (0.45 <= fp <= 0.90):
                continue
            bucket = int((fp - 0.45) / 0.05)
            b = bins.setdefault(bucket, {"n": 0, "w": 0, "sum_fp": 0.0})
            b["n"] += 1
            if pk.get("result") == "W":
                b["w"] += 1
            b["sum_fp"] += fp
        out = []
        for bucket, b in sorted(bins.items()):
            if b["n"] < 5:
                continue
            out.append({
                "bucket_lo": 0.45 + bucket * 0.05,
                "bucket_hi": 0.45 + (bucket + 1) * 0.05,
                "n":         b["n"],
                "expected":  b["sum_fp"] / b["n"],
                "actual":    b["w"] / b["n"],
            })
        return out

    calib_bins = []
    calib_bins_curfilter = []
    try:
        _all = [p for picks in graded_by_date.values() for p in picks]
        calib_bins = _calibration_bins(_all)
        # Current-filter version: only picks that passed Signal >= 3 +
        # EV cushion + not model-only + stayed on until game start.
        _curf = [p for p in _all if plays_log._passes_current_filter(p)]
        calib_bins_curfilter = _calibration_bins(_curf)
    except Exception:
        calib_bins = []
        calib_bins_curfilter = []
    # Trigger the daily analysis in a background thread (fire-and-forget) so
    # /logged never blocks on it. We still read the LATEST available analysis
    # synchronously — on first-ever visit this is None and the UI shows the
    # empty-state card; subsequent visits see yesterday's analysis until the
    # background job finishes writing today's.
    try:
        model_analytics.start_background_analysis()
        analysis = model_analytics.read_latest_analysis() or {
            "insights": [], "lookback_days": 90, "settled_picks": 0,
            "generated_at": None,
        }
    except Exception as e:
        analysis = {"error": str(e), "insights": []}
    try:
        active_adj = model_analytics.active_adjustments_summary()
    except Exception:
        active_adj = {"any": False}
    return render_template_string(
        LOGGED_TEMPLATE,
        fonts_link=FONTS_LINK,
        shared_style=SHARED_STYLE,
        theme_script=THEME_SCRIPT,
        sport_strip=render_sport_strip("logged"),
        summary=summary,
        by_sport=by_sport,
        by_market=by_market,
        by_sport_curfilter=by_sport_curfilter,
        filter_options=filter_options,
        recent_by_filter=recent_by_filter,
        search_date=search_date,
        search_filter=search_filter,
        search_filter_label=search_filter_label,
        search_results=search_results,
        search_record=search_record,
        dates=dates,
        graded_by_date=graded_by_date,
        persist_status=persist_status,
        anchor_status=anchor_status,
        pnl_bars=pnl_bars,
        calib_bins=calib_bins,
        calib_bins_curfilter=calib_bins_curfilter,
        analysis=analysis,
        active_adj=active_adj,
        grader_status=grader_status,
        odds_usage=odds_usage,
        poly_summary=poly_summary,
        shrinkage_recs=shrinkage_recs,
        discord_summary=discord_summary,
        kalshi_summary=kalshi_summary,
        kalshi_recent=kalshi_recent,
    )


@app.route("/debug/kalshi")
def debug_kalshi():
    """Diagnostic: dump raw Kalshi API responses so we can see what
    fields are actually present and where our P&L calculation diverges
    from the user's real account history. Returns JSON — plain text so
    the user can copy/paste a column that doesn't match their statement.

    Shows:
      - is_configured status
      - Field-name audit (which keys the fills/settlements actually use)
      - Last 20 settlements with raw JSON + our computed P&L vs raw revenue
      - Last 50 fills raw JSON (truncated per-field)
      - Per-ticker cost basis derivation (sign of each fill, running total)
      - Our aggregate totals vs sum of raw `revenue`
    """
    import json as _json
    try:
        import kalshi_portfolio as _kp
    except Exception as e:
        return Response(f"kalshi_portfolio import failed: {e}",
                        mimetype="text/plain", status=500)

    if not _kp.is_configured():
        return Response(
            "KALSHI_API_KEY_ID / KALSHI_PRIVATE_KEY_PEM not set. "
            "Add them as Render Secret Files.",
            mimetype="text/plain")

    # Pull raw unfiltered data — bypass caches so a reload reflects the
    # live state after any trades you made since the last tile render.
    try:
        _kp.invalidate_cache()
    except Exception:
        pass

    try:
        from datetime import datetime as _dt, timedelta as _td
        cutoff = int((_dt.utcnow() - _td(days=90)).timestamp())
        settlements = _kp.get_settlements(limit=100, min_ts=cutoff) or []
        fills       = _kp.get_fills(limit=1000, min_ts=max(0, cutoff - 7 * 86400)) or []
    except Exception as e:
        return Response(f"API fetch failed: {e}",
                        mimetype="text/plain", status=500)

    # Field-name audit: Kalshi has had `ticker` vs `market_ticker` field
    # drift historically. Report every key seen on fills + settlements so
    # we can spot mismatches at a glance.
    def _keys(rows):
        seen = {}
        for r in rows or []:
            for k, v in r.items():
                seen.setdefault(k, 0)
                seen[k] += 1
        return dict(sorted(seen.items(), key=lambda x: -x[1]))

    settlement_keys = _keys(settlements)
    fills_keys      = _keys(fills)

    # Possible alias detection: some older Kalshi API versions use
    # `market_ticker` on fills but `ticker` on settlements (or vice
    # versa) — a mismatch here would mean our ticker-based join misses
    # every fill, making cost=0 and triggering the raw-revenue fallback.
    settlement_ticker_key = (
        "ticker" if "ticker" in settlement_keys
        else ("market_ticker" if "market_ticker" in settlement_keys else None))
    fills_ticker_key = (
        "ticker" if "ticker" in fills_keys
        else ("market_ticker" if "market_ticker" in fills_keys else None))

    # Build per-settlement comparison rows using the real Kalshi schema:
    #   revenue (int cents) = gross payout at settlement
    #   yes_total_cost_dollars (str $)   = cost basis of YES side
    #   no_total_cost_dollars  (str $)   = cost basis of NO side
    #   fee_cost (str $)                 = total fees paid
    # Net P&L = revenue - sum(cost dollars * 100) - fee_cost * 100
    rows = []
    agg_our_cents  = 0
    agg_raw_cents  = 0
    agg_cost_cents = 0
    agg_fee_cents  = 0
    for s in settlements:
        tkr = (s.get("ticker") or s.get("market_ticker") or "")
        result = (s.get("market_result") or "").lower()
        yes_qty_fp = s.get("yes_count_fp")
        no_qty_fp  = s.get("no_count_fp")
        yes_cost_c = _kp._dollars_to_cents(s.get("yes_total_cost_dollars"))
        no_cost_c  = _kp._dollars_to_cents(s.get("no_total_cost_dollars"))
        fee_c      = _kp._dollars_to_cents(s.get("fee_cost"))

        raw_rev = s.get("revenue")
        try:
            raw_rev = int(raw_rev) if raw_rev is not None else None
        except Exception:
            raw_rev = None

        if raw_rev is None:
            computed = None
        else:
            computed = raw_rev - yes_cost_c - no_cost_c - fee_c

        # Enumerate fills for this ticker (useful for drill-down even
        # though we no longer need them for the aggregate P&L).
        matched_fills = []
        for f in fills:
            f_tkr = f.get("ticker") or f.get("market_ticker") or ""
            if f_tkr == tkr:
                matched_fills.append(f)

        fill_trace = []
        for f in matched_fills[:20]:   # cap per settlement
            fill_trace.append({
                "outcome_side": f.get("outcome_side"),
                "book_side":    f.get("book_side"),
                "action":       f.get("action"),
                "side":         f.get("side"),
                "count_fp":     f.get("count_fp"),
                "yes_price_dollars": f.get("yes_price_dollars"),
                "no_price_dollars":  f.get("no_price_dollars"),
                "fee_cost":     f.get("fee_cost"),
                "created_time": f.get("created_time"),
            })

        if computed is not None:
            agg_our_cents += computed
        if raw_rev is not None:
            agg_raw_cents += raw_rev
        agg_cost_cents += (yes_cost_c + no_cost_c)
        agg_fee_cents  += fee_c

        rows.append({
            "ticker":          tkr,
            "settled_time":    s.get("settled_time") or "",
            "market_result":   result,
            "yes_count_fp":    yes_qty_fp,
            "no_count_fp":     no_qty_fp,
            "yes_cost_cents":  yes_cost_c,
            "no_cost_cents":   no_cost_c,
            "fee_cents":       fee_c,
            "total_cost_cents": yes_cost_c + no_cost_c + fee_c,
            "raw_revenue_cents": raw_rev,
            "our_pnl_cents":   computed,
            "our_pnl_dollars": round((computed or 0) / 100.0, 2) if computed is not None else None,
            "n_matched_fills": len(matched_fills),
            "fill_trace":      fill_trace,
            "raw_settlement":  s,  # full raw row
        })

    # Overall totals
    totals = {
        "settlements_fetched": len(settlements),
        "fills_fetched":       len(fills),
        "sum_our_pnl_cents":   agg_our_cents,
        "sum_our_pnl_dollars": round(agg_our_cents / 100.0, 2),
        "sum_raw_revenue_cents":   agg_raw_cents,
        "sum_raw_revenue_dollars": round(agg_raw_cents / 100.0, 2),
        "sum_cost_cents":    agg_cost_cents,
        "sum_cost_dollars":  round(agg_cost_cents / 100.0, 2),
        "sum_fee_cents":     agg_fee_cents,
        "sum_fee_dollars":   round(agg_fee_cents / 100.0, 2),
        "formula": "net_pnl = revenue - yes_cost - no_cost - fee_cost",
        "note": ("sum_our_pnl_dollars should match the balance delta you "
                 "see in your Kalshi account over this window. "
                 "sum_raw_revenue_dollars is just gross settlement payouts "
                 "(what Kalshi credited at expiration, before subtracting "
                 "the premium you paid)."),
    }

    out = {
        "configured": True,
        "field_audit": {
            "settlement_keys_seen": settlement_keys,
            "fills_keys_seen":      fills_keys,
            "settlement_ticker_key": settlement_ticker_key,
            "fills_ticker_key":      fills_ticker_key,
        },
        "totals":        totals,
        "settlements":   rows,
        "sample_fills":  fills[:30],   # last 30 raw fills so we can see the field shape
    }
    return Response(_json.dumps(out, indent=2, default=str),
                    mimetype="application/json")


@app.route("/edge-mining")
def edge_mining_page():
    """Phase 31 Round 3 F: mine (sport, market, signal) buckets from
    the last 30-120 days of graded picks for high-hit-rate patterns.
    Each row is a candidate 'edge' — if a (sport, market, signal) is
    hitting 60%+ on >=15 settled picks, that's worth leaning into."""
    import plays_log
    try:
        graded_by_date = plays_log.grade_all(limit_dates=120) or {}
    except Exception:
        graded_by_date = {}
    try:
        import pick_enhancers as _pe
        edges = _pe.compute_edges(graded_by_date, min_n=15, top=30)
    except Exception:
        edges = []
    rows_html = []
    for e in edges:
        units_cls = "pos" if e["units"] > 0 else ("neg" if e["units"] < 0 else "")
        rows_html.append(
            f"<tr>"
            f"<td>{e['sport']}</td>"
            f"<td>{e['market']}</td>"
            f"<td>{e['signal']}</td>"
            f"<td>{e['n']}</td>"
            f"<td><b>{e['hit']:.1f}%</b></td>"
            f"<td class='{units_cls}'>{e['units']:+.2f}u</td>"
            f"</tr>"
        )
    body = (
        FONTS_LINK + SHARED_STYLE
        + '<main class="wrap" style="max-width:900px">'
        + '<h1>Edges</h1>'
        + '<p class="sub" style="color:var(--muted);font-size:13.5px">'
        + 'Historical patterns from last 120 days of graded picks. Buckets with '
        + '>= 15 settled bets, sorted by hit rate.</p>'
        + '<table style="width:100%;border-collapse:collapse;margin-top:14px">'
        + '<thead><tr style="color:var(--muted);font-size:12px;letter-spacing:.08em;text-transform:uppercase">'
        + '<th style="text-align:left;padding:8px">Sport</th>'
        + '<th style="text-align:left;padding:8px">Market</th>'
        + '<th style="text-align:left;padding:8px">Signal</th>'
        + '<th style="text-align:left;padding:8px">N</th>'
        + '<th style="text-align:left;padding:8px">Hit%</th>'
        + '<th style="text-align:left;padding:8px">Units</th>'
        + '</tr></thead><tbody>'
        + ("".join(rows_html) or "<tr><td colspan='6' style='padding:14px;color:var(--muted)'>No edges yet (need >= 15 settled picks per bucket).</td></tr>")
        + '</tbody></table>'
        + '<style>td{padding:8px;border-top:1px solid var(--rule);font-size:14px} .pos{color:var(--good)} .neg{color:var(--bad)}</style>'
        + '</main>' + THEME_SCRIPT
    )
    return body


if __name__ == "__main__":
    import os as _os
    import socket
    # Honor $PORT when it's set (Render, Heroku, Fly, Railway all inject it);
    # fall back to 5000 for local dev. Without this, a Render service that
    # uses `python mlb_ui.py` as its start command would bind to 5000 while
    # Render's port scanner probes $PORT (usually 10000+), producing the
    # "Port scan timeout, no open ports detected" deploy failure.
    port = int(_os.environ.get("PORT") or 5000)
    hostname = socket.gethostname()
    try:
        lan_ip = socket.gethostbyname(hostname)
    except OSError:
        lan_ip = None
    print("Betting Tools - cross-sport Monte Carlo + AI analysis")
    print(f"  On this PC : http://127.0.0.1:{port}")
    if lan_ip and not lan_ip.startswith("127."):
        print(f"  On phone   : http://{lan_ip}:{port}   (same Wi-Fi network)")
    print("  Backtest   : /backtest")
    app.run(debug=False, host="0.0.0.0", port=port)
